const e=[{key:"caie-bio-alevel-topic1",name:"CAIE生物A-Level · Topic 1 细胞结构",description:"细胞结构 · 31 个术语定义（A-Level 生物）",words:[{word:"Adenosine triphosphate (ATP)",phonetic:"",meaning:"A nucleotide derivative which acts as the ‘energy currency’ in cells. It consists of a molecule of ribose joined to the nitrogenous base adenine and three phosphate groups.",example:"三磷酸腺苷（ATP）",image_url:"",emoji:"🔬"},{word:"Capsid",phonetic:"",meaning:"The outer protein shell of a virus that encases and protects the viral genome.",example:"衣壳",image_url:"",emoji:"🔬"},{word:"Cell surface membrane",phonetic:"",meaning:"A phospholipid bilayer studded with proteins that surrounds cells and separates them from their environment.",example:"细胞表面膜（质膜）",image_url:"",emoji:"🔬"},{word:"Cell wall",phonetic:"",meaning:"A permeable layer made of polysaccharides that surrounds plant, algal and fungal cells.",example:"细胞壁",image_url:"",emoji:"🔬"},{word:"Centrioles",phonetic:"",meaning:"Cytoplasmic structures made of microtubules that produce the spindle fibres during mitosis.",example:"中心粒",image_url:"",emoji:"🔬"},{word:"Chloroplast",phonetic:"",meaning:"An organelle found in plants and algae that is the site of photosynthesis.",example:"叶绿体",image_url:"",emoji:"🔬"},{word:"Cilia",phonetic:"",meaning:"Small, hair-like organelles that extend from the surface of eukaryotic cells. They have motile and sensory functions.",example:"纤毛",image_url:"",emoji:"🔬"},{word:"Electron micrograph",phonetic:"",meaning:"An image of a non-living structure produced by a scanning electron microscope (SEM) or a transmission electron microscope (TEM).",example:"电子显微照片",image_url:"",emoji:"🔬"},{word:"Eukaryotic cell",phonetic:"",meaning:"A type of cell that contains a nucleus along with membrane-bound organelles.",example:"真核细胞",image_url:"",emoji:"🔬"},{word:"Eyepiece graticule",phonetic:"",meaning:"A scale bar inside the eyepiece of a light microscope which can be calibrated against a ruler to measure structures.",example:"目镜测微尺",image_url:"",emoji:"🔬"},{word:"Golgi apparatus/ Golgi body/ Golgi complex",phonetic:"",meaning:"An organelle found in eukaryotic cells that is involved in the modification and packaging of proteins.",example:"高尔基体",image_url:"",emoji:"🔬"},{word:"Lysosomes",phonetic:"",meaning:"Membrane-bound vesicles in the cytoplasm that contain a hydrolytic enzyme called lysozyme.",example:"溶酶体",image_url:"",emoji:"🔬"},{word:"Magnification",phonetic:"",meaning:"How much bigger an image appears compared to the original object, calculated using the following formula:",example:"放大倍数",image_url:"",emoji:"🔬"},{word:"Microvilli",phonetic:"",meaning:"Microscopic finger-like projections from the plasma membrane of some animal cells.",example:"微绒毛",image_url:"",emoji:"🔬"},{word:"Mitochondrion (pl mitochondria)",phonetic:"",meaning:"An organelle found in eukaryotic cells that is the site of aerobic respiration.",example:"线粒体",image_url:"",emoji:"🔬"},{word:"Nuclear envelope",phonetic:"",meaning:"A double membrane that surrounds the nucleus.",example:"核膜",image_url:"",emoji:"🔬"},{word:"Nucleolus",phonetic:"",meaning:"A structure found inside the nucleus that contains proteins and RNA and is involved in synthesizing new ribosomes.",example:"核仁",image_url:"",emoji:"🔬"},{word:"Nucleus",phonetic:"",meaning:"An organelle found in eukaryotic cells that stores the genetic information of the cell as chromosomes and is surrounded by a membrane called the nuclear envelope.",example:"细胞核",image_url:"",emoji:"🔬"},{word:"Peptidoglycan",phonetic:"",meaning:"A polymer consisting of amino acids and sugars that forms a 3D mesh and makes up the cell walls of most bacteria.",example:"肽聚糖",image_url:"",emoji:"🔬"},{word:"Photomicrograph",phonetic:"",meaning:"An image produced from a light microscope (also known as an optical microscope).",example:"光学显微照片",image_url:"",emoji:"🔬"},{word:"Plasmodesmata",phonetic:"",meaning:"Microscopic channels between plant cell walls that facilitate symplastic transport.",example:"胞间连丝",image_url:"",emoji:"🔬"},{word:"Prokaryotic cell",phonetic:"",meaning:"A type of cell that does not contain any membrane-bound organelles or a nucleus.",example:"原核细胞",image_url:"",emoji:"🔬"},{word:"Resolution",phonetic:"",meaning:"The ability to distinguish two different points in a specimen.",example:"分辨率",image_url:"",emoji:"🔬"},{word:"Rough endoplasmic reticulum (RER)",phonetic:"",meaning:"A membrane-bound organelle that is involved in the synthesis and packaging of proteins.",example:"粗面内质网（RER）",image_url:"",emoji:"🔬"},{word:"Scanning electron microscope (SEM)",phonetic:"",meaning:"A type of electron microscope that passes a beam of electrons over the surface of a specimen to produce an image.",example:"扫描电子显微镜（SEM）",image_url:"",emoji:"🔬"},{word:"Smooth endoplasmic reticulum (SER)",phonetic:"",meaning:"A membrane-bound organelle involved in lipid synthesis.",example:"光面内质网（SER）",image_url:"",emoji:"🔬"},{word:"Stage micrometer",phonetic:"",meaning:"A scale that may be mounted to the stage of a light microscope and can be used to calibrate an eyepiece graticule.",example:"载物台测微尺",image_url:"",emoji:"🔬"},{word:"Tonoplast",phonetic:"",meaning:"The lipid bilayer that surrounds a permanent vacuole.",example:"液泡膜",image_url:"",emoji:"🔬"},{word:"Transmission electron microscope (TEM)",phonetic:"",meaning:"A type of electron microscope that passes a beam of electrons through a sample to produce an image.",example:"透射电子显微镜（TEM）",image_url:"",emoji:"🔬"},{word:"Vacuole (permanent)",phonetic:"",meaning:"A membrane-bound structure found in plant cells that contains cell sap.",example:"液泡（永久液泡）",image_url:"",emoji:"🔬"},{word:"Viral envelope",phonetic:"",meaning:"The outermost layer of many types of viruses that consists of phospholipids. The envelope protects the viral genome and helps the virus to evade recognition by the host immune system.",example:"病毒包膜",image_url:"",emoji:"🔬"}]},{key:"caie-bio-alevel-topic2",name:"CAIE生物A-Level · Topic 2 生物大分子",description:"生物大分子 · 38 个术语定义（A-Level 生物）",words:[{word:"Alpha glucose",phonetic:"",meaning:"A structural isomer of glucose that exists in a ring form where the hydroxyl group on carbon-1 lies below the plane of the ring.",example:"α-葡萄糖",image_url:"",emoji:"🧪"},{word:"Amino acids",phonetic:"",meaning:"The monomers containing an amino group (NH2), a carboxyl group (COOH) and a variable R group that make up proteins.",example:"氨基酸",image_url:"",emoji:"🧪"},{word:"Amylopectin",phonetic:"",meaning:"A branched polysaccharide made up of alpha glucose monomers joined by α-1,6 glycosidic bonds that makes up starch along with amylose.",example:"支链淀粉",image_url:"",emoji:"🧪"},{word:"Amylose",phonetic:"",meaning:"An unbranched polysaccharide made up of alpha glucose monomers joined by α-1,4 glycosidic bonds that makes up starch along with amylopectin. Benedict’s test - A biochemical test for reducing sugars that produces a different colour based on the amount of reducing sugar present.",example:"直链淀粉",image_url:"",emoji:"🧪"},{word:"Beta glucose",phonetic:"",meaning:"A structural isomer of glucose that exists in a ring form where the hydroxyl group on carbon-1 lies above the plane of the ring.",example:"β-葡萄糖",image_url:"",emoji:"🧪"},{word:"Biuret test",phonetic:"",meaning:"A biochemical test that produces a purple colour when it is added to a solution containing protein.",example:"双缩脲测试",image_url:"",emoji:"🧪"},{word:"Cellulose",phonetic:"",meaning:"A polysaccharide made of beta glucose monomers joined by β-1,4 glycosidic bonds that is used as a structural polysaccharide, providing strength to plant cell walls.",example:"纤维素",image_url:"",emoji:"🧪"},{word:"Collagen",phonetic:"",meaning:"A type of fibrous protein that provides strength to many different cell types and makes up connective tissues.",example:"胶原蛋白",image_url:"",emoji:"🧪"},{word:"Condensation reaction",phonetic:"",meaning:"A type of reaction that joins two molecules together with the formation of a chemical bond involving the elimination of a molecule of water.",example:"缩合反应",image_url:"",emoji:"🧪"},{word:"Disaccharide",phonetic:"",meaning:"Molecules formed by the condensation of two monosaccharides.",example:"二糖",image_url:"",emoji:"🧪"},{word:"Disulfide bond",phonetic:"",meaning:"A covalent bond formed between sulfur-containing cysteine side chains of amino acids.",example:"二硫键",image_url:"",emoji:"🧪"},{word:"Emulsion test",phonetic:"",meaning:"A biochemical test that produces a cloudy emulsion when performed on lipids.",example:"乳液测试（脂肪检测）",image_url:"",emoji:"🧪"},{word:"Fibrous proteins",phonetic:"",meaning:"A class of long chain proteins that are generally insoluble in water and typically have structural roles.",example:"纤维状蛋白",image_url:"",emoji:"🧪"},{word:"Globular proteins",phonetic:"",meaning:"A class of spherical shaped proteins that are generally water-soluble and typically have metabolic roles.",example:"球状蛋白",image_url:"",emoji:"🧪"},{word:"Glycogen",phonetic:"",meaning:"A highly branched polysaccharide made of alpha glucose monomers that is used as the main storage of energy in humans and animals.",example:"糖原",image_url:"",emoji:"🧪"},{word:"Glycosidic bond",phonetic:"",meaning:"A bond between two monosaccharides formed in a condensation reaction.",example:"糖苷键",image_url:"",emoji:"🧪"},{word:"Hydrogen bond",phonetic:"",meaning:"A type of weak bond formed between an electropositive hydrogen and an electronegative atom like oxygen or nitrogen.",example:"氢键",image_url:"",emoji:"🧪"},{word:"Hydrolysis reaction",phonetic:"",meaning:"A type of reaction involving the use of a water molecule that breaks a chemical bond between two molecules.",example:"水解反应",image_url:"",emoji:"🧪"},{word:"Hydrophobic interaction",phonetic:"",meaning:"Polar side chains face the cytosol. Non-polar side chains arrange to minimise the surface area in contact with water and often point inwards.",example:"疏水相互作用",image_url:"",emoji:"🧪"},{word:"Iodine test",phonetic:"",meaning:"A biochemical test that produces a blue/black colour when it is added to a solution containing starch.",example:"碘液测试",image_url:"",emoji:"🧪"},{word:"Latent heat of vapourisation",phonetic:"",meaning:"The amount of energy needed for a substance to change state from a liquid to a gas.",example:"汽化潜热",image_url:"",emoji:"🧪"},{word:"Macromolecule",phonetic:"",meaning:"A large molecule formed by condensation reactions between smaller molecules. Polymers are a type of macromolecule, but not all macromolecules are formed from repeating units.",example:"大分子",image_url:"",emoji:"🧪"},{word:"Monomers",phonetic:"",meaning:"The smaller units from which larger molecules are made.",example:"单体",image_url:"",emoji:"🧪"},{word:"Monosaccharide",phonetic:"",meaning:"The individual sugar monomers from which larger carbohydrates are made.",example:"单糖",image_url:"",emoji:"🧪"},{word:"Non-reducing sugar",phonetic:"",meaning:"A sugar that does not have a free aldehyde or ketone functional group so cannot act as a reducing agent, e.g. sucrose.",example:"非还原糖",image_url:"",emoji:"🧪"},{word:"Peptide bond",phonetic:"",meaning:"The bond between amino acids formed by a condensation reaction between the -H of the amine group on one molecule and the -OH of the carboxylic acid group on the other molecule.",example:"肽键",image_url:"",emoji:"🧪"},{word:"Polymers",phonetic:"",meaning:"Molecules made from a large number of monomers joined together.",example:"聚合物",image_url:"",emoji:"🧪"},{word:"Polysaccharide",phonetic:"",meaning:"Molecules formed by the condensation of many monosaccharides.",example:"多糖",image_url:"",emoji:"🧪"},{word:"Primary structure",phonetic:"",meaning:"The individual sequence of amino acids in a protein.",example:"一级结构",image_url:"",emoji:"🧪"},{word:"Quaternary structure",phonetic:"",meaning:"A structure only applicable to proteins with multiple polypeptide chains that describes the interactions of the different chains.",example:"四级结构",image_url:"",emoji:"🧪"},{word:"Reducing sugar",phonetic:"",meaning:"A sugar that has a free aldehyde or ketone functional group so can act as a reducing agent, e.g. maltose, fructose, glucose.",example:"还原糖",image_url:"",emoji:"🧪"},{word:"Secondary structure",phonetic:"",meaning:"The local interactions of the amino acids in the polypeptide chain resulting in an alpha helix or a beta-pleated sheet.",example:"二级结构",image_url:"",emoji:"🧪"},{word:"Solvent",phonetic:"",meaning:"A substance which other solutes are dissolved in.",example:"溶剂",image_url:"",emoji:"🧪"},{word:"Specific heat capacity",phonetic:"",meaning:"The amount of energy needed to raise the temperature of a substance by a specific amount.",example:"比热容",image_url:"",emoji:"🧪"},{word:"Starch",phonetic:"",meaning:"A polysaccharide made of alpha glucose monomers that is used as the main storage of energy in plants.",example:"淀粉",image_url:"",emoji:"🧪"},{word:"Sucrose",phonetic:"",meaning:"A disaccharide formed by condensation of a glucose molecule and a fructose molecule.",example:"蔗糖",image_url:"",emoji:"🧪"},{word:"Tertiary structure",phonetic:"",meaning:"The way that the whole protein folds to make a three-dimensional structure.",example:"三级结构",image_url:"",emoji:"🧪"},{word:"Triglyceride",phonetic:"",meaning:"A type of lipid formed by the condensation of one molecule of glycerol and three molecules of fatty acid.",example:"甘油三酯",image_url:"",emoji:"🧪"}]},{key:"caie-bio-alevel-topic3",name:"CAIE生物A-Level · Topic 3 酶",description:"酶 · 20 个术语定义（A-Level 生物）",words:[{word:"Activation energy",phonetic:"",meaning:"The amount of energy needed for a reaction to happen.",example:"活化能",image_url:"",emoji:"⚗️"},{word:"Active site",phonetic:"",meaning:"A specific region on an enzyme where the substrate binds and the reaction takes place.",example:"活性位点",image_url:"",emoji:"⚗️"},{word:"Amylase",phonetic:"",meaning:"An enzyme that catalyses the extracellular breakdown of starch.",example:"淀粉酶",image_url:"",emoji:"⚗️"},{word:"Catalase",phonetic:"",meaning:"An enzyme that catalyses the intracellular breakdown of hydrogen peroxide into oxygen and water.",example:"过氧化氢酶",image_url:"",emoji:"⚗️"},{word:"Catalyst",phonetic:"",meaning:"A substance that increases the rate of reaction, often by offering an alternative reaction pathway with a lower activation energy. It is unchanged at the end of the reaction.",example:"催化剂",image_url:"",emoji:"⚗️"},{word:"Colorimeter",phonetic:"",meaning:"A light-sensitive device that measures the absorbance of transmission of certain wavelengths of light by a solution. A colorimeter can be used to investigate the rate of a reaction that involves colour changes.",example:"比色计",image_url:"",emoji:"⚗️"},{word:"Competitive inhibitor",phonetic:"",meaning:"A molecule which binds to the active site of an enzyme and prevents the substrate from binding.",example:"竞争性抑制剂",image_url:"",emoji:"⚗️"},{word:"Enzyme",phonetic:"",meaning:"A globular protein molecule that acts as a biological catalyst and increases the rate of biochemical reactions. Some enzymes work intracellularly and others work extracellularly.",example:"酶",image_url:"",emoji:"⚗️"},{word:"Enzyme/substrate complex",phonetic:"",meaning:"The temporary complex formed when the substrate binds to the active site of the enzyme.",example:"酶-底物复合物",image_url:"",emoji:"⚗️"},{word:"Extracellular enzyme",phonetic:"",meaning:"An enzyme that is secreted by cells and functions outside of cells, e.g. amylase.",example:"胞外酶",image_url:"",emoji:"⚗️"},{word:"Extracellular reaction",phonetic:"",meaning:"A reaction that occurs outside of cells e.g. in the tissue fluid.",example:"胞外反应",image_url:"",emoji:"⚗️"},{word:"Immobilised enzymes",phonetic:"",meaning:"Enzymes which are attached to an inert, insoluble material over which the substrate passes and the reaction takes place.",example:"固定化酶",image_url:"",emoji:"⚗️"},{word:"Induced-fit hypothesis",phonetic:"",meaning:"A model of enzyme action that describes how enzymes undergo subtle conformational changes which exert a strain on bonds in the substrate.",example:"诱导契合假说",image_url:"",emoji:"⚗️"},{word:"Intracellular enzyme",phonetic:"",meaning:"An enzyme that acts within cells, e.g. catalase.",example:"胞内酶",image_url:"",emoji:"⚗️"},{word:"Intracellular reaction",phonetic:"",meaning:"A reaction that occurs within cells.",example:"胞内反应",image_url:"",emoji:"⚗️"},{word:"Lock and key hypothesis",phonetic:"",meaning:"A model of enzyme action that describes how the enzyme will only fit a substrate that has the correct complementary shape to the active site.",example:"锁钥假说",image_url:"",emoji:"⚗️"},{word:"Michaelis-Menten constant (Km)",phonetic:"",meaning:"A value which indicates how strong the affinity between an enzyme and its substrate is.",example:"米氏常数（Km）",image_url:"",emoji:"⚗️"},{word:"Non-competitive inhibitor",phonetic:"",meaning:"An inhibitor which binds to a part of an enzyme which is not the active site (an allosteric site) and prevents the enzyme from functioning.",example:"非竞争性抑制剂",image_url:"",emoji:"⚗️"},{word:"Substrate specificity",phonetic:"",meaning:"The ability of an enzyme to catalyse only a specific reaction or set of reactions which have substrates complementary to the active site of the enzyme.",example:"底物特异性",image_url:"",emoji:"⚗️"},{word:"Vmax",phonetic:"",meaning:"The maximum reaction rate.",example:"最大反应速率（Vmax）",image_url:"",emoji:"⚗️"}]},{key:"caie-bio-alevel-topic4",name:"CAIE生物A-Level · Topic 4 细胞膜与运输",description:"细胞膜与运输 · 22 个术语定义（A-Level 生物）",words:[{word:"Active transport",phonetic:"",meaning:"The active movement of substances from a low concentration to a higher concentration (up their concentration gradient) with the use of energy in the form of ATP.",example:"主动运输",image_url:"",emoji:"🧫"},{word:"Antigen",phonetic:"",meaning:"Marker molecule on the cell surface membrane (usually a protein or glycoprotein) that can be detected by antibodies and triggers an immune response.",example:"抗原",image_url:"",emoji:"🧫"},{word:"Carrier protein",phonetic:"",meaning:"Protein involved in active transport that uses energy in the form of ATP to change conformation.",example:"载体蛋白",image_url:"",emoji:"🧫"},{word:"Cell signalling",phonetic:"",meaning:"Cells release chemicals which bind to complementary receptors on their target and trigger specific responses.",example:"细胞信号传导",image_url:"",emoji:"🧫"},{word:"Cell surface receptor",phonetic:"",meaning:"A component on the cell membrane which binds to extracellular signals.",example:"细胞表面受体",image_url:"",emoji:"🧫"},{word:"Channel proteins",phonetic:"",meaning:"Transmembrane proteins for transporting large or charged substances. Some are involved in facilitated diffusion and do not use ATP; others are involved in active transport and do require energy in the form of ATP.",example:"通道蛋白",image_url:"",emoji:"🧫"},{word:"Cholesterol",phonetic:"",meaning:"A steroid hormone which adds stability to the lipid bilayer.",example:"胆固醇",image_url:"",emoji:"🧫"},{word:"Diffusion",phonetic:"",meaning:"The passive spreading out of substances from a high concentration to a lower concentration (down their concentration gradient) without the use of energy.",example:"扩散",image_url:"",emoji:"🧫"},{word:"Endocytosis",phonetic:"",meaning:"A method of bulk transport into a cell which relies on invagination of the cell membrane and requires energy in the form of ATP.",example:"胞吞作用",image_url:"",emoji:"🧫"},{word:"Exocytosis",phonetic:"",meaning:"A method of bulk transport out of a cell which occurs when vesicles fuse with the cell membrane and release their contents. It requires energy in the form of ATP.",example:"胞吐作用",image_url:"",emoji:"🧫"},{word:"Facilitated diffusion",phonetic:"",meaning:"The passive movement of substances from a high concentration to a lower concentration (down their concentration gradient) through transport proteins without the use of energy.",example:"协助扩散",image_url:"",emoji:"🧫"},{word:"Fluid mosaic model",phonetic:"",meaning:"A model that describes membrane structure as a sea of mobile phospholipids studded with various proteins.",example:"流动镶嵌模型",image_url:"",emoji:"🧫"},{word:"Glycolipid",phonetic:"",meaning:"A lipid which is bound to a monosaccharide or oligosaccharide.",example:"糖脂",image_url:"",emoji:"🧫"},{word:"Glycoprotein",phonetic:"",meaning:"A protein which is bound to a carbohydrate chain.",example:"糖蛋白",image_url:"",emoji:"🧫"},{word:"Ligand",phonetic:"",meaning:"An ion or molecule that transmits signals within or between cells. It has a role in cellular signalling and recognition.",example:"配体",image_url:"",emoji:"🧫"},{word:"Osmosis",phonetic:"",meaning:"The passive diffusion of water molecules from a region of high water potential to a region of lower water potential (down a water potential gradient) through a selectively permeable membrane without the use of energy.",example:"渗透作用",image_url:"",emoji:"🧫"},{word:"Passive transport",phonetic:"",meaning:"The movement of substances without the use of energy.",example:"被动运输",image_url:"",emoji:"🧫"},{word:"Phospholipid",phonetic:"",meaning:"The type of lipid which forms the cell surface membrane bilayer. It is formed by the condensation of one molecule of glycerol, two molecules of fatty acid and a phosphate group. The two fatty acid chains are the non-polar hydrophobic tails whilst the phosphate group is the polar hydrophilic head.",example:"磷脂",image_url:"",emoji:"🧫"},{word:"Phospholipid bilayer",phonetic:"",meaning:"A polar membrane made of two layers of phospholipid molecules. It is a selectively permeable barrier to the passage of ions and molecules into and out of cells.",example:"磷脂双分子层",image_url:"",emoji:"🧫"},{word:"Surface area to volume ratio",phonetic:"",meaning:"The volume of an object compared with the amount of area where it contacts its environment. Calculated by dividing the surface area of an object by its volume.",example:"表面积与体积比",image_url:"",emoji:"🧫"},{word:"Visking tubing",phonetic:"",meaning:"A semipermeable material which can be used to model the cell surface membrane.",example:"透析管（威斯金管）",image_url:"",emoji:"🧫"},{word:"Water potential",phonetic:"",meaning:"A measure of the tendency of water molecules to move from one area to another measured in kilopascals (kPa) and given the symbol Ψ.",example:"水势",image_url:"",emoji:"🧫"}]},{key:"caie-bio-alevel-topic5",name:"CAIE生物A-Level · Topic 5 细胞分裂与DNA",description:"细胞分裂与DNA · 23 个术语定义（A-Level 生物）",words:[{word:"Anaphase",phonetic:"",meaning:"The third stage in mitosis where the chromosomes are pulled apart to the poles of the cell by the spindle fibres.",example:"后期",image_url:"",emoji:"🧬"},{word:"Asexual reproduction",phonetic:"",meaning:"The production of genetically identical offspring from one parent through the process of mitosis.",example:"无性生殖",image_url:"",emoji:"🧬"},{word:"Bivalent",phonetic:"",meaning:"A pair of homologous chromosomes.",example:"二价体（四分体）",image_url:"",emoji:"🧬"},{word:"Centromere",phonetic:"",meaning:"A structure on a chromosome that holds the sister chromatids together.",example:"着丝粒",image_url:"",emoji:"🧬"},{word:"Chromatid",phonetic:"",meaning:"One strand of a replicated chromosome.",example:"染色单体",image_url:"",emoji:"🧬"},{word:"Chromosome",phonetic:"",meaning:"A structure consisting of a long, coiled molecule of DNA and its associated proteins, by which genetic information is passed from generation to generation.",example:"染色体",image_url:"",emoji:"🧬"},{word:"Cytokinesis",phonetic:"",meaning:"The division of the cytoplasm at the end of mitosis to produce two new daughter cells.",example:"胞质分裂",image_url:"",emoji:"🧬"},{word:"Deoxyribonucleic acid (DNA)",phonetic:"",meaning:"An information storing molecule made up of deoxyribonucleotide monomers joined by phosphodiester bonds to form a double helix.",example:"脱氧核糖核酸（DNA）",image_url:"",emoji:"🧬"},{word:"Differentiation",phonetic:"",meaning:"The process where a cell develops certain features so that it is specialised to carry out a certain function.",example:"细胞分化",image_url:"",emoji:"🧬"},{word:"G1 (Gap 1) phase",phonetic:"",meaning:"The first growth phase in interphase during which the cell synthesises proteins and RNA, duplicates its organelles and increases in size before DNA replication in S phase.",example:"G1期（间隙期1）",image_url:"",emoji:"🧬"},{word:"G2 (Gap 2) phase",phonetic:"",meaning:"The second growth phase of interphase during which the cell continues to increase in size and synthesize biomolecules.",example:"G2期（间隙期2）",image_url:"",emoji:"🧬"},{word:"Histone proteins",phonetic:"",meaning:"Proteins that, together with DNA, form chromosomes in the nuclei of eukaryotic cells.",example:"组蛋白",image_url:"",emoji:"🧬"},{word:"Homologous chromosomes",phonetic:"",meaning:"Two chromosomes with the same gene loci but different alleles, one inherited from each parent.",example:"同源染色体",image_url:"",emoji:"🧬"},{word:"Metaphase",phonetic:"",meaning:"The second stage of mitosis in which replicated chromosomes align at the equator of the cell.",example:"中期",image_url:"",emoji:"🧬"},{word:"Mitosis",phonetic:"",meaning:"The division of a cell to produce two genetically identical daughter cells.",example:"有丝分裂",image_url:"",emoji:"🧬"},{word:"Mitotic spindle",phonetic:"",meaning:"A structure mainly consisting of microtubules that is formed by the cytoskeleton between centrioles. Chromosomes attach to the spindle via the kinetochore at their centrosome.",example:"有丝分裂纺锤体",image_url:"",emoji:"🧬"},{word:"Prophase",phonetic:"",meaning:"The first stage in mitosis where the nuclear envelope breaks down, the centrosomes move to opposite poles of the cell, the mitotic spindle begins to form and the chromosomes condense.",example:"前期",image_url:"",emoji:"🧬"},{word:"S (synthesis) phase",phonetic:"",meaning:"The second phase in the cell cycle where the DNA in the cell is replicated.",example:"S期（合成期）",image_url:"",emoji:"🧬"},{word:"Sister chromatids",phonetic:"",meaning:"A pair of identical chromatids formed by DNA replication, joined by a centromere.",example:"姐妹染色单体",image_url:"",emoji:"🧬"},{word:"Stem cell",phonetic:"",meaning:"A type of undifferentiated cell which has the ability to divide many times and differentiate into many different cell types.",example:"干细胞",image_url:"",emoji:"🧬"},{word:"Telomere",phonetic:"",meaning:"A sequence of repeating nucleotides at each end of a chromosome. During DNA replication, the end of the lagging strand either is not replicated or remains as an RNA-DNA complex. Without telomeres, the chromosome would get shorter with continued replication and some genetic information may be lost.",example:"端粒",image_url:"",emoji:"🧬"},{word:"Telophase",phonetic:"",meaning:"The final stage of mitosis in which new nuclear envelopes begin to form around the separated sets of chromosomes.",example:"末期",image_url:"",emoji:"🧬"},{word:"Tumour",phonetic:"",meaning:"An abnormal growth of tissue resulting from uncontrolled mitosis.",example:"肿瘤",image_url:"",emoji:"🧬"}]},{key:"caie-bio-alevel-topic6",name:"CAIE生物A-Level · Topic 6 遗传与蛋白质合成",description:"遗传与蛋白质合成 · 34 个术语定义（A-Level 生物）",words:[{word:"Anticodon",phonetic:"",meaning:"A sequence of three nucleotide bases at one end of a tRNA molecule that is specific to an mRNA codon.",example:"反密码子",image_url:"",emoji:"🧬"},{word:"Antiparallel",phonetic:"",meaning:"Describes the complementary strands of a DNA double helix which run parallel but in opposite directions (5’ to 3’ and 3’ to 5’).",example:"反向平行",image_url:"",emoji:"🧬"},{word:"Complementary base pairing",phonetic:"",meaning:"Describes how hydrogen bonds form between complementary purine and pyrimidine bases. Two bonds form between A and T in DNA or U in RNA. Three bonds form between G and C.",example:"碱基互补配对",image_url:"",emoji:"🧬"},{word:"Deletion mutation",phonetic:"",meaning:"A form of gene mutation in which one or more nucleotide bases are removed from a DNA sequence.",example:"缺失突变",image_url:"",emoji:"🧬"},{word:"DNA ligase",phonetic:"",meaning:"An enzyme that catalyses the formation of phosphodiester bonds between Okazaki fragments on the lagging strand during DNA replication.",example:"DNA连接酶",image_url:"",emoji:"🧬"},{word:"DNA nucleotide",phonetic:"",meaning:"The monomer that makes up DNA and consists of deoxyribose, a nitrogenous base and a phosphate group.",example:"DNA核苷酸",image_url:"",emoji:"🧬"},{word:"DNA polymerase",phonetic:"",meaning:"An enzyme that catalyses the formation of phosphodiester bonds between nucleotides during the synthesis of a new DNA strand.",example:"DNA聚合酶",image_url:"",emoji:"🧬"},{word:"Exons",phonetic:"",meaning:"Regions of DNA or RNA that code for amino acid sequences.",example:"外显子",image_url:"",emoji:"🧬"},{word:"Gene",phonetic:"",meaning:"A sequence of nucleotides on a chromosome that codes for the production of one or more polypeptide chains and functional RNA.",example:"基因",image_url:"",emoji:"🧬"},{word:"Gene mutation",phonetic:"",meaning:"A change to at least one nucleotide base in DNA or the arrangement of bases. Gene mutations can occur spontaneously during DNA replication.",example:"基因突变",image_url:"",emoji:"🧬"},{word:"Insertion mutation",phonetic:"",meaning:"A form of gene mutation in which one or more nucleotide bases are added to a DNA sequence.",example:"插入突变",image_url:"",emoji:"🧬"},{word:"Interphase",phonetic:"",meaning:"The longest stage of the eukaryotic cell cycle. It consists of G1 phase, S phase and G2 phase and occurs before mitosis. DNA replication occurs during S phase.",example:"间期",image_url:"",emoji:"🧬"},{word:"Introns",phonetic:"",meaning:"Non-coding sequences of DNA found between exons.",example:"内含子",image_url:"",emoji:"🧬"},{word:"Lagging strand",phonetic:"",meaning:"The DNA strand that is synthesised discontinuously in the 3’ to 5’ direction (away from the replication fork) during semi-conservative replication.",example:"滞后链",image_url:"",emoji:"🧬"},{word:"Leading strand",phonetic:"",meaning:"The DNA strand that is synthesised continuously in the 5’ to 3’ direction (towards the replication fork) during sem-conservating replication.",example:"前导链",image_url:"",emoji:"🧬"},{word:"Messenger RNA (mRNA)",phonetic:"",meaning:"A type of RNA that carries genetic information from the nucleus to the ribosomes for protein synthesis. It is a single helix consisting of thousands of mononucleotides.",example:"信使RNA（mRNA）",image_url:"",emoji:"🧬"},{word:"Non-transcribed strand",phonetic:"",meaning:"The strand of DNA whose base sequence corresponds to that of the mRNA transcript synthesised during transcription (although it has T instead of U).",example:"非转录链（编码链）",image_url:"",emoji:"🧬"},{word:"Nucleotide",phonetic:"",meaning:"The monomer from which nucleic acids are made that consists of a pentose sugar, nitrogenous base and phosphate group.",example:"核苷酸",image_url:"",emoji:"🧬"},{word:"Phosphodiester bond",phonetic:"",meaning:"A type of bond that joins nucleotides together to create polynucleotides.",example:"磷酸二酯键",image_url:"",emoji:"🧬"},{word:"Polypeptide",phonetic:"",meaning:"Molecules formed by the condensation of many amino acids.",example:"多肽",image_url:"",emoji:"🧬"},{word:"Purine",phonetic:"",meaning:"A class of nitrogenous bases which are made up of two rings. Adenine and guanine are members.",example:"嘌呤",image_url:"",emoji:"🧬"},{word:"Pyrimidine",phonetic:"",meaning:"A class of nitrogenous bases which are made up of a single ring. Cytosine, thymine and uracil are members.",example:"嘧啶",image_url:"",emoji:"🧬"},{word:"Ribonucleic acid (RNA)",phonetic:"",meaning:"A relatively short molecule made up of ribonucleotide monomers joined by phosphodiester bonds.",example:"核糖核酸（RNA）",image_url:"",emoji:"🧬"},{word:"Ribosomes",phonetic:"",meaning:"Organelles found either free in the cytoplasm or bound to the ER that are involved in the synthesis of proteins.",example:"核糖体",image_url:"",emoji:"🧬"},{word:"RNA nucleotide",phonetic:"",meaning:"The monomer that makes up RNA and consists of ribose, a nitrogenous base and a phosphate group.",example:"RNA核苷酸",image_url:"",emoji:"🧬"},{word:"RNA polymerase",phonetic:"",meaning:"An enzyme that catalyses the formation of phosphodiester bonds between nucleotides during the synthesis of a new RNA strand.",example:"RNA聚合酶",image_url:"",emoji:"🧬"},{word:"Semi-conservative replication",phonetic:"",meaning:"The replication of DNA to produce two new DNA molecules which both contain one new strand and one strand from the original DNA molecule.",example:"半保留复制",image_url:"",emoji:"🧬"},{word:"Sickle cell anaemia",phonetic:"",meaning:"A disease characterised by hook-shaped red blood cells. A missense point mutation of GAG to GTG in the HbA (normal) allele for the β-globin polypeptide results in the HbS (sickle cell) allele of the gene.",example:"镰状细胞贫血",image_url:"",emoji:"🧬"},{word:"Substitution mutation",phonetic:"",meaning:"A form of gene mutation in which one nucleotide base is exchanged for another. This may change an amino acid or produce the same amino acid (due to the degeneracy of the genetic code). Transcribed strand -The DNA strand that acts as a template for RNA polymerase during transcription. Also known as the template strand.",example:"替换突变",image_url:"",emoji:"🧬"},{word:"Transcription",phonetic:"",meaning:"The formation of pre-mRNA in eukaryotes and mRNA in prokaryotes from a section of the template strand of DNA. It is the first stage of protein synthesis.",example:"转录",image_url:"",emoji:"🧬"},{word:"Transfer RNA (tRNA)",phonetic:"",meaning:"A form of RNA that carries specific amino acids to the ribosomes. It is single-stranded and takes a clover-leaf shape. One side is longer than the other enabling the attachment of an amino acid. At the opposite end is an anticodon specific to the amino acid.",example:"转运RNA（tRNA）",image_url:"",emoji:"🧬"},{word:"Translation",phonetic:"",meaning:"The second phase of protein synthesis that takes place on the ribosomes. mRNA is used as a template for the attachment of tRNA molecules with complementary anticodons. The amino acids carried on adjacent tRNA molecules are joined to form a polypeptide chain.",example:"翻译",image_url:"",emoji:"🧬"},{word:"Triplet code",phonetic:"",meaning:"A specific sequence of three nucleotides on a molecule of DNA or RNA codes for a particular amino acid in protein synthesis.",example:"三联体密码",image_url:"",emoji:"🧬"},{word:"Universal",phonetic:"",meaning:"A feature of the genetic code; the same codons code for the same amino acids in almost all organisms.",example:"通用性（遗传密码通用）",image_url:"",emoji:"🧬"}]},{key:"caie-bio-alevel-topic7",name:"CAIE生物A-Level · Topic 7 植物运输",description:"植物运输 · 27 个术语定义（A-Level 生物）",words:[{word:"Adhesion (water movement)",phonetic:"",meaning:"The formation of hydrogen bonds between carbohydrates in the xylem vessel walls and water molecules. This contributes to the capillarity of water and transpiration pull.",example:"附着力（水分运动）",image_url:"",emoji:"🌿"},{word:"Apoplastic pathway",phonetic:"",meaning:"One of two pathways by which water and minerals move across the root. Water moves through intercellular spaces between cellulose molecules in the cell wall.",example:"质外体途径",image_url:"",emoji:"🌿"},{word:"Casparian strip",phonetic:"",meaning:"A waterproof strip surrounding the endodermal cells of the root that blocks the apoplast pathway, forcing water through the symplast route.",example:"凯氏带",image_url:"",emoji:"🌿"},{word:"Cohesion (water movement)",phonetic:"",meaning:"The formation of hydrogen bonds between water molecules. This contributes to the capillarity of water and transpiration pull.",example:"内聚力（水分运动）",image_url:"",emoji:"🌿"},{word:"Cohesion-tension theory",phonetic:"",meaning:"The model that explains the movement of water from the soil to the leaves in a continuous stream.",example:"内聚-张力理论",image_url:"",emoji:"🌿"},{word:"Companion cells",phonetic:"",meaning:"Active cells of the phloem located adjacent to the sieve tube elements which produce ATP for metabolic processes in both themselves and the sieve tube elements. They retain their nucleus and organelles.",example:"伴胞",image_url:"",emoji:"🌿"},{word:"Cotransport",phonetic:"",meaning:"A form of secondary active transport. The movement of one substance down its concentration or electrochemical gradient is coupled to the transport of another substance via transmembrane proteins.",example:"协同运输",image_url:"",emoji:"🌿"},{word:"Dicotyledonous plants",phonetic:"",meaning:"Plants that produce seeds that contain two cotyledons. They have two primary leaves.",example:"双子叶植物",image_url:"",emoji:"🌿"},{word:"Endodermis",phonetic:"",meaning:"The innermost layer of the cortex of a dicotyledon root. It is impregnated with suberin which forms the Casparian strip. Endodermal cells actively transport mineral ions into the xylem.",example:"内皮层",image_url:"",emoji:"🌿"},{word:"Evaporation",phonetic:"",meaning:"A transition from the liquid state to the gaseous state which requires heat energy.",example:"蒸发",image_url:"",emoji:"🌿"},{word:"Herbaceous plants",phonetic:"",meaning:"Plants which do not have woody stems.",example:"草本植物",image_url:"",emoji:"🌿"},{word:"Hydrostatic pressure",phonetic:"",meaning:"The force which fluid molecules exert on the walls of a vessel.",example:"静水压",image_url:"",emoji:"🌿"},{word:"Lignin",phonetic:"",meaning:"An organic polymer that has a role in the support and impermeability of vascular tissues.",example:"木质素",image_url:"",emoji:"🌿"},{word:"Mass flow",phonetic:"",meaning:"Sugars flow passively from the source to the sink down a hydrostatic pressure gradient.",example:"集流（质量流）",image_url:"",emoji:"🌿"},{word:"Phloem",phonetic:"",meaning:"A living plant transport vessel responsible for the transfer of assimilates to all parts of the plant. The phloem consists of sieve tube elements and companion cells.",example:"韧皮部",image_url:"",emoji:"🌿"},{word:"Potometer",phonetic:"",meaning:"An apparatus used to measure water uptake from a cut shoot.",example:"蒸腾仪",image_url:"",emoji:"🌿"},{word:"Root hair cells",phonetic:"",meaning:"Specialised cells responsible for the uptake of water and minerals from the soil. They have long hair-like extensions known as root hairs, which are adapted as exchange surfaces.",example:"根毛细胞",image_url:"",emoji:"🌿"},{word:"Sieve plates",phonetic:"",meaning:"The perforated end walls of sieve tube elements that allow plant assimilates to flow between cells unimpeded.",example:"筛板",image_url:"",emoji:"🌿"},{word:"Sieve tube elements",phonetic:"",meaning:"The main cells of the phloem. They are elongated cells laid end-to-end with sieve plates between. They contain few organelles.",example:"筛管分子",image_url:"",emoji:"🌿"},{word:"Sinks (plants)",phonetic:"",meaning:"The regions of a plant that remove assimilates e.g. roots, meristem, fruits.",example:"库（植物）",image_url:"",emoji:"🌿"},{word:"Sources (plants)",phonetic:"",meaning:"The regions of a plant that produce assimilates e.g. leaves, storage organs.",example:"源（植物）",image_url:"",emoji:"🌿"},{word:"Suberin",phonetic:"",meaning:"A waterproof, waxy material that forms the Casparian strip in the endodermis.",example:"木栓质",image_url:"",emoji:"🌿"},{word:"Symplastic pathway",phonetic:"",meaning:"One of two pathways by which water and minerals move across the root. Water enters the cytoplasm through the plasma membrane and moves between adjacent cells via plasmodesmata. Water diffuses down its water potential gradient by osmosis.",example:"共质体途径",image_url:"",emoji:"🌿"},{word:"Translocation",phonetic:"",meaning:"The bulk movement of organic compounds in plants from sources to sinks via the phloem.",example:"易位（运输作用）",image_url:"",emoji:"🌿"},{word:"Transpiration",phonetic:"",meaning:"Water loss from plant leaves and stems via diffusion and evaporation. The rate of transpiration is affected by light, temperature, humidity, air movement and soil-water availability.",example:"蒸腾作用",image_url:"",emoji:"🌿"},{word:"Xerophytes",phonetic:"",meaning:"Plants that are adapted to live and reproduce in dry habitats where water availability is low, e.g. cacti and marram grass.",example:"旱生植物",image_url:"",emoji:"🌿"},{word:"Xylem",phonetic:"",meaning:"A non-living, heavily lignified plant transport vessel responsible for the transfer of water and minerals from the roots to the shoots and leaves.",example:"木质部",image_url:"",emoji:"🌿"}]},{key:"caie-bio-alevel-topic8",name:"CAIE生物A-Level · Topic 8 血液循环",description:"血液循环 · 48 个术语定义（A-Level 生物）",words:[{word:"Affinity",phonetic:"",meaning:"The tendency of one substance to bind with another substance.",example:"亲和力",image_url:"",emoji:"❤️"},{word:"Aorta",phonetic:"",meaning:"The artery that takes oxygenated blood away from the heart to the body.",example:"主动脉",image_url:"",emoji:"❤️"},{word:"Arteriole",phonetic:"",meaning:"A type of blood vessel that connects the arteries and capillaries. The walls of the arterioles contain large amounts of smooth muscle, some elastic fibres and some collagen.",example:"小动脉",image_url:"",emoji:"❤️"},{word:"Artery",phonetic:"",meaning:"A type of blood vessel that carries blood away from the heart to the tissues under high pressure. The walls of the arteries contain collagen, smooth muscle and elastic fibres.",example:"动脉",image_url:"",emoji:"❤️"},{word:"Atrial systole",phonetic:"",meaning:"The stage of the cardiac cycle in which the atria contract, pushing blood into the ventricles. The AV valves are pushed open fully and the atria are emptied of blood.",example:"心房收缩期",image_url:"",emoji:"❤️"},{word:"Atrioventricular node (AVN)",phonetic:"",meaning:"A group of cells located between the atria that slow down the wave of excitation and pass it between the ventricles along the bundle of His.",example:"房室结（AVN）",image_url:"",emoji:"❤️"},{word:"Atrioventricular valves (AV valves)",phonetic:"",meaning:"The valves found between the atria and ventricles. They prevent the backflow of blood from the ventricles into the atria. There are two types of atrioventricular valves: bicuspid and tricuspid.",example:"房室瓣（AV瓣）",image_url:"",emoji:"❤️"},{word:"Atrium",phonetic:"",meaning:"Chamber of the heart that receives blood from the veins.",example:"心房",image_url:"",emoji:"❤️"},{word:"Bicuspid valves",phonetic:"",meaning:"The atrioventricular valves found between the left atrium and left ventricle.",example:"二尖瓣（僧帽瓣）",image_url:"",emoji:"❤️"},{word:"Blood",phonetic:"",meaning:"The transport medium in the mammalian circulatory system. It consists of plasma, red blood cells, white blood cells and platelets.",example:"血液",image_url:"",emoji:"❤️"},{word:"Bohr shift",phonetic:"",meaning:"The loss of affinity of haemoglobin for oxygen as the partial pressure of carbon dioxide increases.",example:"波尔效应（波尔位移）",image_url:"",emoji:"❤️"},{word:"Bundle of His",phonetic:"",meaning:"A collection of Purkyne fibres which run from the AVN down to the apex of the ventricles.",example:"希氏束",image_url:"",emoji:"❤️"},{word:"Capillaries",phonetic:"",meaning:"Microscopic blood vessels that form a large network through the tissues of the body and connect the arterioles to the venules. They are the site of exchange of substances between the blood and the tissues.",example:"毛细血管",image_url:"",emoji:"❤️"},{word:"Carbaminohaemoglobin",phonetic:"",meaning:"A compound formed when carbon dioxide reversibly binds to amine groups in haemoglobin.",example:"氨基甲酰血红蛋白",image_url:"",emoji:"❤️"},{word:"Carbonic anhydrase",phonetic:"",meaning:"An enzyme that catalyses the reversible reaction between water and carbon dioxide to produce carbonic acid.",example:"碳酸酐酶",image_url:"",emoji:"❤️"},{word:"Cardiac cycle",phonetic:"",meaning:"Describes the sequence of events involved in one complete contraction and relaxation of the heart. There are three stages: atrial systole, ventricular systole and diastole.",example:"心动周期",image_url:"",emoji:"❤️"},{word:"Chloride shift",phonetic:"",meaning:"The process by which chloride ions move into the erythrocytes in exchange for hydrogen carbonate ions which diffuse out of the erythrocytes. This is a one-to-one exchange and it maintains the electrochemical equilibrium of the cell.",example:"氯离子转移",image_url:"",emoji:"❤️"},{word:"Circulatory system",phonetic:"",meaning:"The transport system in animals.",example:"循环系统",image_url:"",emoji:"❤️"},{word:"Closed circulatory system",phonetic:"",meaning:"A circulatory system in which the blood pumped by the heart is contained within blood vessels. The blood does not come into direct contact with the cells. Closed circulatory systems are found in animals, e.g. vertebrates.",example:"闭管式循环系统",image_url:"",emoji:"❤️"},{word:"Diastole",phonetic:"",meaning:"The stage of the cardiac cycle in which the heart muscle relaxes. The atria and ventricles fill with blood. The AV valves are open.",example:"舒张期",image_url:"",emoji:"❤️"},{word:"Double circulatory system",phonetic:"",meaning:"A circulatory system in which the blood flows through the heart twice in two circuits. Blood is pumped from the heart to the lungs before returning to the heart. It is then pumped around the body, after which it returns to the heart again. Double circulatory systems are found in mammals.",example:"双循环系统",image_url:"",emoji:"❤️"},{word:"Elastic arteries",phonetic:"",meaning:"Large vessels that receive blood directly from the heart at high pressure. They contain large numbers of collagen and elastic fibres.",example:"弹性动脉",image_url:"",emoji:"❤️"},{word:"Haemoglobin",phonetic:"",meaning:"The red pigment found in erythrocytes that binds reversibly with four oxygen molecules to form oxyhaemoglobin. It is a globular protein that consists of four polypeptide chains, each with a prosthetic haem group.",example:"血红蛋白",image_url:"",emoji:"❤️"},{word:"Haemoglobinic acid",phonetic:"",meaning:"The product formed when haemoglobin accepts free hydrogen ions. This enables haemoglobin to act as a buffer which reduces changes in blood pH.",example:"血红蛋白酸",image_url:"",emoji:"❤️"},{word:"Inferior vena cava",phonetic:"",meaning:"The vein that returns deoxygenated blood to the heart from the lower body.",example:"下腔静脉",image_url:"",emoji:"❤️"},{word:"Left ventricle",phonetic:"",meaning:"The chamber of the heart that receives oxygenated blood from the left atrium and pumps it through the aorta around the body. The left ventricle is thicker than the right ventricle as it must pump blood further at a higher pressure.",example:"左心室",image_url:"",emoji:"❤️"},{word:"Lymphocytes",phonetic:"",meaning:"White blood cells that contribute to the specific immune response e.g. B lymphocytes can differentiate to produce antibodies.",example:"淋巴细胞",image_url:"",emoji:"❤️"},{word:"Monocytes",phonetic:"",meaning:"White blood cells that become tissue macrophages and perform phagocytosis.",example:"单核细胞",image_url:"",emoji:"❤️"},{word:"Muscular artery",phonetic:"",meaning:"A medium-sized vessel that takes blood from an elastic artery and branches into smaller arteries and arterioles. Muscular arteries contain large amounts of smooth muscle.",example:"肌性动脉",image_url:"",emoji:"❤️"},{word:"Neutrophils",phonetic:"",meaning:"White blood cells with a multi-lobed nucleus that perform phagocytosis and release chemicals which contribute to fever and inflammation.",example:"中性粒细胞",image_url:"",emoji:"❤️"},{word:"Oncotic pressure",phonetic:"",meaning:"The movement of water into the blood by osmosis due to the tendency of plasma proteins to lower the water potential of the blood.",example:"胶体渗透压",image_url:"",emoji:"❤️"},{word:"Oxygen dissociation curve",phonetic:"",meaning:"A graph that describes the relationship between the partial pressure of oxygen and the percentage saturation of haemoglobin in the blood.",example:"氧解离曲线",image_url:"",emoji:"❤️"},{word:"Plasma",phonetic:"",meaning:"The main component of the blood that carries red blood cells. It is a yellow liquid that contains proteins, nutrients, mineral ions, hormones, dissolved gases and waste.",example:"血浆",image_url:"",emoji:"❤️"},{word:"Pulmonary arteries",phonetic:"",meaning:"The arteries that carry deoxygenated blood away from the heart to the lungs.",example:"肺动脉",image_url:"",emoji:"❤️"},{word:"Pulmonary veins",phonetic:"",meaning:"The veins that carry oxygenated blood from the lungs to the heart.",example:"肺静脉",image_url:"",emoji:"❤️"},{word:"Purkyne tissue",phonetic:"",meaning:"Specialised cardiac muscle fibres which make up the bundle of His and conduct the wave of excitation through the septum from the AVN down to the apex of the ventricles.",example:"浦肯野组织",image_url:"",emoji:"❤️"},{word:"Red blood cells (erythrocytes)",phonetic:"",meaning:"A type of blood cell that is anucleate and biconcave. It contains haemoglobin which enables the transport of oxygen and carbon dioxide to and from the tissues.",example:"红细胞（红血球）",image_url:"",emoji:"❤️"},{word:"Right ventricle",phonetic:"",meaning:"The chamber of the heart that receives deoxygenated blood from the right ventricle and pumps it through the pulmonary vein to the lungs. The right ventricle is thinner than the left ventricle as it pumps blood a shorter distance at a lower pressure.",example:"右心室",image_url:"",emoji:"❤️"},{word:"Semilunar valves",phonetic:"",meaning:"A pair of valves found between the ventricles and arteries. They prevent the backflow of blood from the arteries into the ventricles.",example:"半月瓣",image_url:"",emoji:"❤️"},{word:"Septum",phonetic:"",meaning:"The wall of muscle which separates the left side of the heart from the right side of the heart, preventing oxygenated and deoxygenated blood from mixing.",example:"隔膜（室间隔）",image_url:"",emoji:"❤️"},{word:"Sinoatrial node (SAN)",phonetic:"",meaning:"A group of cells in the wall of the right atrium that generate electrical activity, causing the atria to contract. The SAN is often referred to as the heart’s pacemaker.",example:"窦房结（SAN）",image_url:"",emoji:"❤️"},{word:"Superior vena cava",phonetic:"",meaning:"The vein that returns deoxygenated blood to the heart from the head and upper body.",example:"上腔静脉",image_url:"",emoji:"❤️"},{word:"Tissue fluid",phonetic:"",meaning:"The fluid that surrounds the cells of animals. It has the same composition as plasma but does not contain red blood cells or plasma proteins.",example:"组织液",image_url:"",emoji:"❤️"},{word:"Tricuspid valves",phonetic:"",meaning:"The atrioventricular valves found between the right atrium and right ventricle.",example:"三尖瓣",image_url:"",emoji:"❤️"},{word:"Vein",phonetic:"",meaning:"A type of blood vessel that carries blood towards the heart under low pressure. It has a wide lumen, a smooth inner lining and valves. The walls of the veins contain smooth muscle, large amounts of collagen and little elastic fibre.",example:"静脉",image_url:"",emoji:"❤️"},{word:"Ventricle",phonetic:"",meaning:"Chamber of the heart which receives blood from the atria.",example:"心室",image_url:"",emoji:"❤️"},{word:"Ventricular systole",phonetic:"",meaning:"The stage of the cardiac cycle in which the ventricles contract, pushing blood into the arteries. The semilunar valves are pushed open fully.",example:"心室收缩期",image_url:"",emoji:"❤️"},{word:"Venule",phonetic:"",meaning:"A type of blood vessel that connects the capillaries and veins. The walls of the venules contain small amounts of collagen and smooth muscle.",example:"小静脉",image_url:"",emoji:"❤️"}]},{key:"caie-bio-alevel-topic9",name:"CAIE生物A-Level · Topic 9 气体交换",description:"气体交换 · 14 个术语定义（A-Level 生物）",words:[{word:"Alveolus (pl alveoli)",phonetic:"",meaning:"Tiny air sacs that serve as the primary gaseous exchange surface. They consist of a thin epithelial cell layer, collagen and elastic fibres.",example:"肺泡",image_url:"",emoji:"🫁"},{word:"Bronchioles",phonetic:"",meaning:"Many small divisions of the bronchi. They contain smooth muscle to restrict airflow to the lungs but do not have cartilage. They are lined with a thin layer of ciliated epithelial cells.",example:"细支气管",image_url:"",emoji:"🫁"},{word:"Bronchus (pl bronchi)",phonetic:"",meaning:"Divisions of the trachea that lead into the lungs. They are small tubes supported by incomplete rings of cartilage.",example:"支气管",image_url:"",emoji:"🫁"},{word:"Cartilage",phonetic:"",meaning:"Strong, flexible connective tissue that supports the walls of the trachea and bronchi, preventing collapse.",example:"软骨",image_url:"",emoji:"🫁"},{word:"Ciliated epithelium",phonetic:"",meaning:"Specialised cells found lining the trachea which have tiny hair-like cilia that waft mucus up to the back of the throat, where it is swallowed.",example:"纤毛上皮",image_url:"",emoji:"🫁"},{word:"Elastic fibres",phonetic:"",meaning:"Fibres of elastin that allow the alveoli to stretch as air is drawn in and recoil to expel air. They are also found in the trachea, bronchi and bronchioles.",example:"弹性纤维",image_url:"",emoji:"🫁"},{word:"Exchange surface",phonetic:"",meaning:"A surface over which materials are exchanged from one region to another. An effective exchange surface has a large surface area, thin layers, a good blood supply, and ventilation to maintain a steep diffusion gradient.",example:"交换表面",image_url:"",emoji:"🫁"},{word:"Goblet cells",phonetic:"",meaning:"Specialised cells that secrete mucus onto the trachea lining. The mucus traps harmful substances and microorganisms, preventing their entry into the lungs.",example:"杯状细胞",image_url:"",emoji:"🫁"},{word:"Lungs",phonetic:"",meaning:"The primary organs of the mammalian respiratory system.",example:"肺",image_url:"",emoji:"🫁"},{word:"Mammalian gas exchange system",phonetic:"",meaning:"A complex system found in mammals in which oxygen and carbon dioxide gases are exchanged.",example:"哺乳动物气体交换系统",image_url:"",emoji:"🫁"},{word:"Mucous glands",phonetic:"",meaning:"Glands which contain clusters of mucous-secreting cells.",example:"黏液腺",image_url:"",emoji:"🫁"},{word:"Smooth muscle",phonetic:"",meaning:"Involuntary muscle found in the walls of the trachea and bronchi. It constricts the lumen of the bronchi by contracting, reducing airflow to the lungs.",example:"平滑肌",image_url:"",emoji:"🫁"},{word:"Squamous epithelium",phonetic:"",meaning:"A single layer of flattened epithelial cells.",example:"鳞状上皮（扁平上皮）",image_url:"",emoji:"🫁"},{word:"Trachea (mammals)",phonetic:"",meaning:"The main airway that acts as a passage for air to pass to and from the bronchi. It is a tube supported by incomplete rings of cartilage.",example:"气管（哺乳动物）",image_url:"",emoji:"🫁"}]},{key:"caie-bio-alevel-topic10",name:"CAIE生物A-Level · Topic 10 疾病与免疫",description:"疾病与免疫 · 20 个术语定义（A-Level 生物）",words:[{word:"Acquired Immunodeficiency Syndrome (AIDS)",phonetic:"",meaning:"A disease which occurs when HIV destroys a given proportion of T helper cells and the immune system is no longer functional.",example:"获得性免疫缺陷综合征（艾滋病）",image_url:"",emoji:"🦠"},{word:"Antibiotic",phonetic:"",meaning:"A chemical or compound produced by a living organism that kills or prevents the growth of bacteria.",example:"抗生素",image_url:"",emoji:"🦠"},{word:"Antibiotic resistance",phonetic:"",meaning:"Some bacteria have favourable mutations which allow them to survive in the presence of an antibiotic. These bacteria reproduce rapidly to form resistant strains.",example:"抗生素耐药性",image_url:"",emoji:"🦠"},{word:"Bacteria",phonetic:"",meaning:"Prokaryotic cells that have cell walls but lack organelles. Some bacteria are pathogenic, producing toxins that damage host cells.",example:"细菌",image_url:"",emoji:"🦠"},{word:"Bacterial mutation",phonetic:"",meaning:"Random changes in the DNA sequence may result in a protein with an altered primary, and therefore tertiary structure.",example:"细菌突变",image_url:"",emoji:"🦠"},{word:"Cholera",phonetic:"",meaning:"A disease caused by some strains of the bacterium Vibrio cholerae. It causes severe diarrhoea.",example:"霍乱",image_url:"",emoji:"🦠"},{word:"Disease",phonetic:"",meaning:"Dysregulation of a living system that impairs function.",example:"疾病",image_url:"",emoji:"🦠"},{word:"Human Immunodeficiency Virus (HIV)",phonetic:"",meaning:"An infectious virus that destroys T helper cells, weakening the immune system of the body. HIV makes an individual more susceptible to opportunistic infections and can lead to AIDS (Acquired Immunodeficiency Syndrome).",example:"人类免疫缺陷病毒（HIV）",image_url:"",emoji:"🦠"},{word:"Infectious disease",phonetic:"",meaning:"A disease that is caused by a pathogen and transmitted directly between organisms.",example:"传染病",image_url:"",emoji:"🦠"},{word:"Malaria",phonetic:"",meaning:"A disease caused by the protoctists Plasmodium falciparum, Plasmodium malariae, Plasmodium ovale and Plasmodium vivax that live within two hosts, mosquitoes and humans. It causes recurrent episodes of fever and can be fatal.",example:"疟疾",image_url:"",emoji:"🦠"},{word:"Measles",phonetic:"",meaning:"A disease caused by the virus of the genus Morbillivirus. It causes cold-like symptoms and fever.",example:"麻疹",image_url:"",emoji:"🦠"},{word:"Non-infectious disease",phonetic:"",meaning:"A disease that cannot be transmitted by direct contact between individuals e.g. sickle cell anaemia or lung cancer.",example:"非传染病",image_url:"",emoji:"🦠"},{word:"Pathogen",phonetic:"",meaning:"A disease-causing microorganism. Includes bacteria, viruses, fungi and protoctista.",example:"病原体",image_url:"",emoji:"🦠"},{word:"Penicillin",phonetic:"",meaning:"The first conventional, effective and safe antibiotic derived from the mould Penicillium chrysogenum. It was discovered by Alexander Flemming.",example:"青霉素",image_url:"",emoji:"🦠"},{word:"Protoctista",phonetic:"",meaning:"A group of eukaryotic, single-celled microorganisms that may cause disease. They digest cells and use the cell contents to reproduce.",example:"原生生物",image_url:"",emoji:"🦠"},{word:"Selection pressure",phonetic:"",meaning:"Environmental factor that drives evolution by natural selection.",example:"选择压力",image_url:"",emoji:"🦠"},{word:"Smallpox",phonetic:"",meaning:"A disease caused by viruses of the Variola genus. The initial symptoms are headache and fever. Later there is pockmarking of the skin. The World Health Organisation registers that the disease has been eradicated due to a successful vaccination program.",example:"天花",image_url:"",emoji:"🦠"},{word:"Tuberculosis (TB)",phonetic:"",meaning:"A bacterial disease, caused by Mycobacterium tuberculosis and M. bovis, that damages lung tissue and weakens the immune system.",example:"结核病（TB）",image_url:"",emoji:"🦠"},{word:"Vector (disease)",phonetic:"",meaning:"A living or non-living agent that transmits a pathogen between organisms.",example:"媒介（疾病传播媒介）",image_url:"",emoji:"🦠"},{word:"Virus",phonetic:"",meaning:"Non-living infectious agents that invade host cells and take over cell metabolism, replicating within them.",example:"病毒",image_url:"",emoji:"🦠"}]},{key:"caie-bio-alevel-topic11",name:"CAIE生物A-Level · Topic 11 免疫应答",description:"免疫应答 · 34 个术语定义（A-Level 生物）",words:[{word:"Active immunity",phonetic:"",meaning:"Resistance in an organism that has developed through the production of specific antibodies in response to a pathogen. It provides long-lasting immunity as memory cells are produced.",example:"主动免疫",image_url:"",emoji:"🛡️"},{word:"Anti-toxins",phonetic:"",meaning:"Chemicals produced by white blood cells that neutralise toxins released by pathogens.",example:"抗毒素",image_url:"",emoji:"🛡️"},{word:"Antibodies",phonetic:"",meaning:"Immunoglobulins produced by B-lymphocytes in response to a specific antigen, triggering an immune response.",example:"抗体",image_url:"",emoji:"🛡️"},{word:"Antigen-presenting cell",phonetic:"",meaning:"A macrophage that displays foreign antigens.",example:"抗原呈递细胞",image_url:"",emoji:"🛡️"},{word:"Artificial active immunity",phonetic:"",meaning:"The production of antibodies by the immune system following the exposure to a weakened, attenuated or dead pathogen e.g. by vaccination.",example:"人工主动免疫",image_url:"",emoji:"🛡️"},{word:"Artificial passive immunity",phonetic:"",meaning:"The immunity acquired from the administration of specific antibodies from another organism.",example:"人工被动免疫",image_url:"",emoji:"🛡️"},{word:"B-effector cells",phonetic:"",meaning:"A type of B-lymphocyte that divides to form plasma cells.",example:"B效应细胞",image_url:"",emoji:"🛡️"},{word:"B-lymphocytes",phonetic:"",meaning:"Lymphocytes that mature in the bone marrow. There are three main types: plasma cells, B-effector cells and B-memory cells.",example:"B淋巴细胞",image_url:"",emoji:"🛡️"},{word:"B-memory cells",phonetic:"",meaning:"B-lymphocytes that provide immunological memory.",example:"B记忆细胞",image_url:"",emoji:"🛡️"},{word:"Clonal expansion",phonetic:"",meaning:"Rapid mitosis of specific antibody-producing cells.",example:"克隆扩增",image_url:"",emoji:"🛡️"},{word:"Clonal selection",phonetic:"",meaning:"The identification of an antibody-producing cell with complementary receptors to the shape of a specific antigen.",example:"克隆选择",image_url:"",emoji:"🛡️"},{word:"Hybridoma method",phonetic:"",meaning:"A method used to produce large numbers of monoclonal antibodies. An antigen is injected into a mammal to stimulate clonal expansion of complementary B-cells. These B-cells are harvested and fused with a myeloma, which can undergo mitosis an indefinite number of times. The hybrid cell line is called a hybridoma.",example:"杂交瘤技术",image_url:"",emoji:"🛡️"},{word:"Immune response",phonetic:"",meaning:"The body’s response to antigens it identifies as ‘non-self’ consists of a non-specific phase involving neutrophils and macrophages, and a specific phase involving T- and B-lymphocytes.",example:"免疫应答",image_url:"",emoji:"🛡️"},{word:"Memory cells",phonetic:"",meaning:"A subtype of lymphocyte which is produced after primary infection and remains in low levels in the blood. These cells undergo rapid mitosis if the same pathogen is encountered again.",example:"记忆细胞",image_url:"",emoji:"🛡️"},{word:"Monoclonal antibodies",phonetic:"",meaning:"Identical antibodies that have been produced by an immune cell cloned from a parent cell.",example:"单克隆抗体",image_url:"",emoji:"🛡️"},{word:"Natural active immunity",phonetic:"",meaning:"The production of antibodies by the immune system following infection.",example:"自然主动免疫",image_url:"",emoji:"🛡️"},{word:"Natural passive immunity",phonetic:"",meaning:"The immunity acquired by an infant mammal when antibodies are transferred through the placenta and the colostrum from the mother.",example:"自然被动免疫",image_url:"",emoji:"🛡️"},{word:"Non-self antigens",phonetic:"",meaning:"Foreign antigens that originate from outside the body and induce an immune response.",example:"非己抗原",image_url:"",emoji:"🛡️"},{word:"Non-specific immune response",phonetic:"",meaning:"The first line of defence against all non-self antigens involving phagocytosis by neutrophils and macrophages.",example:"非特异性免疫应答",image_url:"",emoji:"🛡️"},{word:"Passive immunity",phonetic:"",meaning:"Resistance in an organism acquired via the transfer of antibodies. It provides short-term immunity as no memory cells are produced.",example:"被动免疫",image_url:"",emoji:"🛡️"},{word:"Phagocytes",phonetic:"",meaning:"Specialised white blood cells that engulf and destroy pathogens. There are two types: neutrophils and macrophages.",example:"吞噬细胞",image_url:"",emoji:"🛡️"},{word:"Phagocytosis",phonetic:"",meaning:"The process by which phagocytes engulf and destroy pathogens.",example:"吞噬作用",image_url:"",emoji:"🛡️"},{word:"Phagolysosome",phonetic:"",meaning:"A vesicle within a phagocyte formed by the fusion of a phagosome and lysosome.",example:"吞噬溶酶体",image_url:"",emoji:"🛡️"},{word:"Phagosome",phonetic:"",meaning:"The vacuole inside a phagocyte in which a foreign particle is engulfed.",example:"吞噬体",image_url:"",emoji:"🛡️"},{word:"Plasma cell",phonetic:"",meaning:"A type of B lymphocyte that produces antibodies specific to a particular antigen.",example:"浆细胞",image_url:"",emoji:"🛡️"},{word:"Primary immune response",phonetic:"",meaning:"The response of the immune system to a pathogen when it is first encountered. A small number of antibodies are produced slowly.",example:"初次免疫应答",image_url:"",emoji:"🛡️"},{word:"Secondary immune response",phonetic:"",meaning:"The response of the immune system to a pathogen when it is encountered for a second (third, fourth…etc.) time. Immunological memory gives a rapid production of a large number of antibodies.",example:"二次免疫应答",image_url:"",emoji:"🛡️"},{word:"Self antigens",phonetic:"",meaning:"Antigens present on an organism’s cells that are tolerated by their own immune system. They induce antibody formation in other organisms.",example:"自身抗原",image_url:"",emoji:"🛡️"},{word:"Specific immune response",phonetic:"",meaning:"The second line of defence against substances with non-self antigens begins when complementary T-helper cells bind to the antigen and secrete interleukins that trigger rapid mitosis of complementary B-cells or T-killer cells.",example:"特异性免疫应答",image_url:"",emoji:"🛡️"},{word:"T-helper cells",phonetic:"",meaning:"T-lymphocytes with CD4 receptors on the cell surface membrane. These bind to antigens on antigen-presenting cells and secrete interleukins.",example:"T辅助细胞",image_url:"",emoji:"🛡️"},{word:"T-killer cells",phonetic:"",meaning:"T-lymphocytes that produce perforin, destroying pathogens with a specific antigen.",example:"T杀伤细胞",image_url:"",emoji:"🛡️"},{word:"T-lymphocyte",phonetic:"",meaning:"Lymphocytes that mature in the thymus gland. There are four main types: T-helper cells, T-killer cells, T-memory cells and T-regulatory cells.",example:"T淋巴细胞",image_url:"",emoji:"🛡️"},{word:"T-memory cells",phonetic:"",meaning:"T-lymphocytes that provide immunological memory.",example:"T记忆细胞",image_url:"",emoji:"🛡️"},{word:"Vaccination",phonetic:"",meaning:"The deliberate exposure of an individual to antigens from a pathogen to provide artificial active immunity.",example:"疫苗接种",image_url:"",emoji:"🛡️"}]},{key:"caie-bio-alevel-topic12",name:"CAIE生物A-Level · Topic 12 能量与呼吸",description:"Energy and Respiration · 42 个术语定义（A-Level 生物）",words:[{word:"Acetyl coenzyme A",phonetic:"",meaning:"A two-carbon molecule formed in the link reaction when an acetyl group is bound by coenzyme A. It is oxidised in the Krebs cycle.",example:"乙酰辅酶A",image_url:"",emoji:"🔬"},{word:"Adenosine triphosphate (ATP)",phonetic:"",meaning:"The universal energy carrier found in all living cells.",example:"腺苷三磷酸（ATP）",image_url:"",emoji:"🔬"},{word:"Aerenchyma",phonetic:"",meaning:"Spongy tissue with air spaces that allow gas exchange between the shoots and the roots of some plants e.g. rice.",example:"通气组织",image_url:"",emoji:"🔬"},{word:"Aerobic respiration",phonetic:"",meaning:"A form of cellular respiration that takes place in the presence of oxygen and produces carbon dioxide, water and ATP. Overall: C6H12O6 + 6O2 → 6CO2 + 6H2O",example:"有氧呼吸",image_url:"",emoji:"🔬"},{word:"Anabolic reactions",phonetic:"",meaning:"Smaller molecules react to form larger molecules. This requires an energy input.",example:"合成代谢反应",image_url:"",emoji:"🔬"},{word:"Anaerobic respiration",phonetic:"",meaning:"A form of cellular respiration that takes place in the absence of oxygen. It produces less ATP than aerobic respiration.",example:"无氧呼吸",image_url:"",emoji:"🔬"},{word:"ATP synthase",phonetic:"",meaning:"An enzyme found embedded in cellular membranes that phosphorylates ADP to form ATP as protons flow through it.",example:"ATP合酶",image_url:"",emoji:"🔬"},{word:"Chemiosmosis",phonetic:"",meaning:"The synthesis of ATP through the movement of protons down their concentration gradient across a semipermeable membrane, catalysed by ATP synthase.",example:"化学渗透",image_url:"",emoji:"🔬"},{word:"Citrate",phonetic:"",meaning:"A six-carbon molecule formed in the first stage of the Krebs cycle from the reaction of acetyl coenzyme A and oxaloacetate.",example:"柠檬酸",image_url:"",emoji:"🔬"},{word:"Coenzyme",phonetic:"",meaning:"A molecule that helps enzymes carry out their function e.g. NAD, FAD, coenzyme A.",example:"辅酶",image_url:"",emoji:"🔬"},{word:"Coenzyme A",phonetic:"",meaning:"A coenzyme that binds an acetyl group to form acetyl coenzyme A during the link reaction of aerobic respiration.",example:"辅酶A",image_url:"",emoji:"🔬"},{word:"Cristae",phonetic:"",meaning:"Folds of the inner mitochondrial membrane that provide a large surface area for oxidative phosphorylation.",example:"线粒体嵴",image_url:"",emoji:"🔬"},{word:"DCPIP",phonetic:"",meaning:"An artificial hydrogen acceptor that changes colour from blue to colourless when reduced.",example:"DCPIP（二氯酚靛酚）",image_url:"",emoji:"🔬"},{word:"Decarboxylation",phonetic:"",meaning:"The removal of a carbon dioxide molecule.",example:"脱羧作用",image_url:"",emoji:"🔬"},{word:"Dehydrogenation",phonetic:"",meaning:"The removal of a hydrogen atom.",example:"脱氢作用",image_url:"",emoji:"🔬"},{word:"Electron acceptor",phonetic:"",meaning:"Oxygen acts as the final electron acceptor in the electron transfer chain: ½O2 + 2e- + 2H+ → H2O",example:"电子受体",image_url:"",emoji:"🔬"},{word:"Electron carriers",phonetic:"",meaning:"Protein molecules that accept and release electrons e.g. NAD.",example:"电子载体",image_url:"",emoji:"🔬"},{word:"Electron transport chain",phonetic:"",meaning:"A series of electron carrier proteins that transfer electrons in a chain of oxidation-reduction reactions.",example:"电子传递链",image_url:"",emoji:"🔬"},{word:"FAD",phonetic:"",meaning:"A coenzyme that becomes reduced when it takes up hydrogen atoms during the Krebs cycle, forming reduced FAD.",example:"FAD（黄素腺嘌呤二核苷酸）",image_url:"",emoji:"🔬"},{word:"Fructose 1,6-bisphosphate",phonetic:"",meaning:"A six-carbon molecule formed by the phosphorylation of glucose during glycolysis. It splits into two molecules of triose phosphate.",example:"果糖-1,6-二磷酸",image_url:"",emoji:"🔬"},{word:"Glucose",phonetic:"",meaning:"A six-carbon monosaccharide which is an important respiratory substrate.",example:"葡萄糖",image_url:"",emoji:"🔬"},{word:"Glycolysis",phonetic:"",meaning:"An anaerobic process that takes place in the cytosol of the cell and breaks down glucose into two molecules of pyruvate. Two molecules of ATP and two molecules of reduced NAD are also formed.",example:"糖酵解",image_url:"",emoji:"🔬"},{word:"Inner mitochondrial membrane",phonetic:"",meaning:"The mitochondrial membrane that separates the matrix from the intermembrane space. It is the site of the electron transport chain.",example:"线粒体内膜",image_url:"",emoji:"🔬"},{word:"Intermembrane space",phonetic:"",meaning:"The small space between the inner and outer mitochondrial membranes. The electron transport chain results in a high proton concentration here.",example:"线粒体膜间隙",image_url:"",emoji:"🔬"},{word:"Krebs cycle",phonetic:"",meaning:"A series of oxidation-reduction reactions in the matrix of the mitochondria in which acetyl coenzyme A is oxidised, generating reduced NAD, reduced FAD, ATP and carbon dioxide.",example:"克雷布斯循环（三羧酸循环）",image_url:"",emoji:"🔬"},{word:"Lactate dehydrogenase",phonetic:"",meaning:"An enzyme that catalyses the conversion of pyruvate to lactate.",example:"乳酸脱氢酶",image_url:"",emoji:"🔬"},{word:"Link reaction",phonetic:"",meaning:"The first stage of aerobic respiration (also known as oxidative decarboxylation). It takes place in the mitochondrial matrix and converts pyruvate into acetyl coenzyme A and carbon dioxide. Reduced NAD is also formed. Overall: Pyruvate + NAD + CoA → acetyl CoA + reduced NAD + CO2",example:"连接反应",image_url:"",emoji:"🔬"},{word:"Methylene blue",phonetic:"",meaning:"An artificial hydrogen acceptor that changes colour from blue to colourless when reduced.",example:"亚甲蓝",image_url:"",emoji:"🔬"},{word:"Mitochondrial matrix",phonetic:"",meaning:"The fluid-filled space within the inner membrane of the mitochondria which contains mitochondrial DNA and enzymes required for aerobic respiration.",example:"线粒体基质",image_url:"",emoji:"🔬"},{word:"Mitochondrion",phonetic:"",meaning:"An organelle found in eukaryotic cells that is the site of aerobic respiration.",example:"线粒体",image_url:"",emoji:"🔬"},{word:"NAD",phonetic:"",meaning:"A coenzyme that becomes reduced when it takes up hydrogen atoms during aerobic respiration, forming reduced NAD.",example:"NAD（烟酰胺腺嘌呤二核苷酸）",image_url:"",emoji:"🔬"},{word:"Outer mitochondrial membrane",phonetic:"",meaning:"The membrane segregating the contents of the mitochondrion from the rest of the cell. It creates optimal conditions for aerobic respiration.",example:"线粒体外膜",image_url:"",emoji:"🔬"},{word:"Oxaloacetate",phonetic:"",meaning:"A four-carbon molecule that combines with acetyl coenzyme A to produce six-carbon citrate in the first stage of the Krebs cycle. It is eventually regenerated, allowing the cycle to continue.",example:"草酰乙酸",image_url:"",emoji:"🔬"},{word:"Oxidative phosphorylation",phonetic:"",meaning:"The synthesis of ATP from reduced coenzymes and oxygen in the electron transport chain of aerobic respiration.",example:"氧化磷酸化",image_url:"",emoji:"🔬"},{word:"Oxygen debt",phonetic:"",meaning:"The amount of additional oxygen required after a burst of anaerobic respiration to restore the body to a resting state.",example:"氧债",image_url:"",emoji:"🔬"},{word:"Pyruvate",phonetic:"",meaning:"A three-carbon molecule produced in glycolysis. In the link reaction of aerobic respiration, it is oxidised to acetate. During fermentation, it is converted to lactate (animals) or ethanol and carbon dioxide (plants and microorganisms).",example:"丙酮酸",image_url:"",emoji:"🔬"},{word:"Redox indicator",phonetic:"",meaning:"A substance which changes colour when it gains or loses electrons.",example:"氧化还原指示剂",image_url:"",emoji:"🔬"},{word:"Respiratory quotient",phonetic:"",meaning:"The ratio of carbon dioxide produced to oxygen consumed during respiration. Calculated using:",example:"呼吸商",image_url:"",emoji:"🔬"},{word:"Respiratory substrate",phonetic:"",meaning:"An organic molecule that can be broken down via the respiratory pathways to produce ATP.",example:"呼吸底物",image_url:"",emoji:"🔬"},{word:"Respirometer",phonetic:"",meaning:"A device used to determine respiration rate in living organisms by measuring the change in volume of oxygen or carbon dioxide.",example:"呼吸计",image_url:"",emoji:"🔬"},{word:"Substrate-level phosphorylation",phonetic:"",meaning:"The synthesis of ATP by the transfer of a phosphate group from a phosphorylated intermediate to ADP.",example:"底物水平磷酸化",image_url:"",emoji:"🔬"},{word:"Triose phosphate",phonetic:"",meaning:"A three-carbon compound formed in glycolysis.",example:"磷酸丙糖",image_url:"",emoji:"🔬"}]},{key:"caie-bio-alevel-topic13",name:"CAIE生物A-Level · Topic 13 光合作用",description:"Photosynthesis · 42 个术语定义（A-Level 生物）",words:[{word:"Absorption spectrum",phonetic:"",meaning:"A graph which plots absorption of radiation against wavelength or frequency of light.",example:"吸收光谱",image_url:"",emoji:"🔬"},{word:"Action spectrum",phonetic:"",meaning:"A graph which plots biological activity of a system against the wavelength of light.",example:"作用光谱",image_url:"",emoji:"🔬"},{word:"ATP synthase",phonetic:"",meaning:"An enzyme found embedded in cellular membranes that phosphorylates ADP to form ATP as protons flow through it.",example:"ATP合酶",image_url:"",emoji:"🔬"},{word:"Calvin cycle",phonetic:"",meaning:"See ‘Light-independent reaction’.",example:"卡尔文循环",image_url:"",emoji:"🔬"},{word:"Carotenes",phonetic:"",meaning:"A group of photosynthetic carotenoid pigments which absorb blue, violet and ultraviolet wavelengths of light, and reflect orange and red wavelengths of light.",example:"胡萝卜素",image_url:"",emoji:"🔬"},{word:"Chlorophyll",phonetic:"",meaning:"A photosynthetic pigment located in the thylakoids of chloroplasts that absorbs light energy. There are two main types, chlorophyll a and chlorophyll b.",example:"叶绿素",image_url:"",emoji:"🔬"},{word:"Chlorophyll a",phonetic:"",meaning:"The main photosynthetic pigment. It absorbs orange-red and violet-blue wavelengths of light, and reflects green-yellow light.",example:"叶绿素a",image_url:"",emoji:"🔬"},{word:"Chlorophyll b",phonetic:"",meaning:"An accessory photosynthetic pigment which can absorb a higher frequency of blue light than chlorophyll a.",example:"叶绿素b",image_url:"",emoji:"🔬"},{word:"Chloroplast",phonetic:"",meaning:"An organelle found in plants and algae that is the site of photosynthesis.",example:"叶绿体",image_url:"",emoji:"🔬"},{word:"Chromatography",phonetic:"",meaning:"The process of separating different substances from a mixture.",example:"层析法",image_url:"",emoji:"🔬"},{word:"Cyclic photophosphorylation",phonetic:"",meaning:"The formation of ATP involving photosystem I only. Photoactivation of chlorophyll takes place.",example:"循环光合磷酸化",image_url:"",emoji:"🔬"},{word:"DCPIP",phonetic:"",meaning:"An artificial hydrogen acceptor that changes colour from blue to colourless when reduced.",example:"DCPIP（二氯酚靛酚）",image_url:"",emoji:"🔬"},{word:"Electron carriers",phonetic:"",meaning:"Protein molecules that accept and release electrons e.g. NADP.",example:"电子载体",image_url:"",emoji:"🔬"},{word:"Glycerate 3-phosphate (GP)",phonetic:"",meaning:"A three-carbon molecule that is reduced by reduced NADP in the light-independent stage of photosynthesis to form two molecules of TP. This requires ATP.",example:"3-磷酸甘油酸（GP）",image_url:"",emoji:"🔬"},{word:"Grana",phonetic:"",meaning:"Stacks of thylakoids connected by intergranal lamellae.",example:"基粒",image_url:"",emoji:"🔬"},{word:"Hill reaction",phonetic:"",meaning:"During the light-dependent reaction of photosynthesis, the transfer of electrons due to photoionisation can be observed using a redox indicator.",example:"希尔反应",image_url:"",emoji:"🔬"},{word:"Lamellae",phonetic:"",meaning:"Membranous channels that connect adjacent grana in a chloroplast.",example:"片层结构",image_url:"",emoji:"🔬"},{word:"Light-dependent reaction",phonetic:"",meaning:"The first stage of photosynthesis that uses light energy to produce ATP, reduced NADP and oxygen. It takes place in the thylakoids of the chloroplast.",example:"光依赖反应（光反应）",image_url:"",emoji:"🔬"},{word:"Light-harvesting system",phonetic:"",meaning:"A collection of protein and chlorophyll molecules found in the thylakoid membranes of chloroplasts that absorbs light energy of varying wavelengths and transfers it to the reaction centre. It is also known as an antennae complex.",example:"捕光系统",image_url:"",emoji:"🔬"},{word:"Light-independent reaction",phonetic:"",meaning:"The second stage of photosynthesis, also known as the Calvin cycle, in which the products of the light-dependent stage and carbon dioxide are used to build organic molecules. It does not require light energy and takes place in the stroma.",example:"光独立反应（暗反应）",image_url:"",emoji:"🔬"},{word:"Limiting factor",phonetic:"",meaning:"A variable that limits the rate of a particular reaction.",example:"限制因素",image_url:"",emoji:"🔬"},{word:"Methylene blue",phonetic:"",meaning:"An artificial hydrogen acceptor that changes colour from blue to colourless when reduced.",example:"亚甲蓝",image_url:"",emoji:"🔬"},{word:"NADP",phonetic:"",meaning:"A coenzyme that becomes reduced when it takes up hydrogen atoms during the light-dependent stage of photosynthesis, forming reduced NADP.",example:"NADP（烟酰胺腺嘌呤二核苷酸磷酸）",image_url:"",emoji:"🔬"},{word:"Non-cyclic photophosphorylation",phonetic:"",meaning:"The formation of ATP and reduced NADP involving both photosystems I and II. Photoactivation of chlorophyll takes place.",example:"非循环光合磷酸化",image_url:"",emoji:"🔬"},{word:"Non-photochemical quenching",phonetic:"",meaning:"Excess energy from the excitation of chlorophyll is dissipated.",example:"非光化学猝灭",image_url:"",emoji:"🔬"},{word:"Photoactivation",phonetic:"",meaning:"The initiation of a process by the absorption of photons of light energy.",example:"光活化",image_url:"",emoji:"🔬"},{word:"Photolysis",phonetic:"",meaning:"The splitting of a molecule of water in the presence of light that occurs during the light-dependent stage of photosynthesis. This produces protons, electrons and oxygen: H2O → 2H+ + 2e- + ½O2",example:"光解",image_url:"",emoji:"🔬"},{word:"Photophosphorylation",phonetic:"",meaning:"The harnessing of light energy in photosynthesis to phosphorylate ADP, forming ATP.",example:"光合磷酸化",image_url:"",emoji:"🔬"},{word:"Photorespiration",phonetic:"",meaning:"The enzyme rubisco has both carboxylase and oxygenase activity, so some of the substrate undergoes oxidation rather than carboxylation.",example:"光呼吸",image_url:"",emoji:"🔬"},{word:"Photosynthesis",phonetic:"",meaning:"A complex metabolic pathway that synthesises organic molecules in the presence of light. It consists of three main stages: capturing of light energy, light-dependent reaction, light-independent reaction. Overall: 6CO2 + 6H2O → C6H12O6 + 6O2",example:"光合作用",image_url:"",emoji:"🔬"},{word:"Photosynthetic pigments",phonetic:"",meaning:"Molecules present in chloroplasts that absorb certain wavelengths of light e.g. chlorophyll a, chlorophyll b, xanthophylls and carotenoids.",example:"光合色素",image_url:"",emoji:"🔬"},{word:"Photosystem",phonetic:"",meaning:"A protein complex consisting of a light-harvesting system and reaction centre, that is involved in the absorption of light and transfer of electrons in photosynthesis.",example:"光系统",image_url:"",emoji:"🔬"},{word:"Reaction centre",phonetic:"",meaning:"The region of a photosystem where energy is funneled and photosynthetic reactions take place. It contains two chlorophyll a molecules.",example:"反应中心",image_url:"",emoji:"🔬"},{word:"Redox indicator",phonetic:"",meaning:"A substance which changes colour when it gains or loses electrons.",example:"氧化还原指示剂",image_url:"",emoji:"🔬"},{word:"Retardation factor (Rf) value",phonetic:"",meaning:"Indicates the solubility of a substance in a particular solvent. A high Rf value represents high solubility. Calculated using the equation:",example:"比移值（Rf值）",image_url:"",emoji:"🔬"},{word:"Ribulose bisphosphate (RuBP)",phonetic:"",meaning:"A five-carbon compound that reacts with carbon dioxide in the light-independent stage of photosynthesis, forming two molecules of GP.",example:"核酮糖二磷酸（RuBP）",image_url:"",emoji:"🔬"},{word:"Rubisco",phonetic:"",meaning:"An enzyme that catalyses the reaction of RuBP and carbon dioxide in the light-independent stage of photosynthesis.",example:"Rubisco（核酮糖二磷酸羧化酶/加氧酶）",image_url:"",emoji:"🔬"},{word:"Stroma",phonetic:"",meaning:"The fluid interior of chloroplasts that contains the enzymes required for the light-independent reaction.",example:"叶绿体基质",image_url:"",emoji:"🔬"},{word:"Thin-layer chromatography (TLC)",phonetic:"",meaning:"A technique used to separate photosynthetic pigments by their rate of movement when carried by a solvent, across an inert surface. Differences in rate arise due to varying solubilities in the mobile phase and interactions with the stationary phase.",example:"薄层色谱法（TLC）",image_url:"",emoji:"🔬"},{word:"Thylakoids",phonetic:"",meaning:"A series of flattened membrane-bound compartments in chloroplasts. They are stacked to form grana and contain the chlorophyll and other molecules needed for the light-dependent reaction.",example:"类囊体",image_url:"",emoji:"🔬"},{word:"Triose phosphate (TP)",phonetic:"",meaning:"A three-carbon compound formed in the light-independent stage of photosynthesis. It may serve as a starting material for the formation of organic molecules or be used to regenerate RuBP.",example:"磷酸丙糖（TP）",image_url:"",emoji:"🔬"},{word:"Xanthophylls",phonetic:"",meaning:"A group of yellow-coloured carotenoid pigments which probably aid non-photochemical quenching.",example:"叶黄素",image_url:"",emoji:"🔬"}]},{key:"caie-bio-alevel-topic14",name:"CAIE生物A-Level · Topic 14 稳态调节",description:"Homeostasis · 67 个术语定义（A-Level 生物）",words:[{word:"Abscisic acid (ABA)",phonetic:"",meaning:"A plant hormone that stimulates stomatal cloning, maintains seed dormancy and triggers cold protective responses.",example:"脱落酸（ABA）",image_url:"",emoji:"🔬"},{word:"Afferent arteriole",phonetic:"",meaning:"The larger diameter arteriole which carries blood to the glomerulus for ultrafiltration.",example:"入球小动脉",image_url:"",emoji:"🔬"},{word:"Antidiuretic hormone (ADH)",phonetic:"",meaning:"A hormone released from the posterior pituitary gland that increases the reabsorption of water in the kidney tubules.",example:"抗利尿激素（ADH）",image_url:"",emoji:"🔬"},{word:"Aquaporin",phonetic:"",meaning:"A membrane channel used for the selective transport of water in and out of the cell.",example:"水通道蛋白",image_url:"",emoji:"🔬"},{word:"Autonomic nervous system",phonetic:"",meaning:"A branch of the nervous system that carries nerve impulses to muscles and glands. It controls involuntary activities and has two divisions: the sympathetic nervous system and the parasympathetic nervous system.",example:"自主神经系统",image_url:"",emoji:"🔬"},{word:"Biosensor",phonetic:"",meaning:"A biological molecule is paired with a device that generates a thermal, optical or electrical signal when a specific reaction takes place in order to detect the presence of a particular chemical.",example:"生物传感器",image_url:"",emoji:"🔬"},{word:"Bowman’s capsule",phonetic:"",meaning:"The cup-like structure at the start of a nephron that surrounds the glomerulus. The inner layer of the capsule, through which filtration of the blood takes place, is composed of podocytes.",example:"鲍曼氏囊（肾小囊）",image_url:"",emoji:"🔬"},{word:"Central nervous system (CNS)",phonetic:"",meaning:"The brain and spinal cord.",example:"中枢神经系统（CNS）",image_url:"",emoji:"🔬"},{word:"Collecting ducts",phonetic:"",meaning:"A system of ducts and tubules which connect nephrons to a calyx or the renal pelvis which is a site for water reabsorption.",example:"集合管",image_url:"",emoji:"🔬"},{word:"Coordinator",phonetic:"",meaning:"Coordinates information from the receptors and sends instructions to the effectors.",example:"协调中枢",image_url:"",emoji:"🔬"},{word:"Cortex",phonetic:"",meaning:"The outer region of the kidney.",example:"肾皮质",image_url:"",emoji:"🔬"},{word:"Cyclic AMP (cAMP)",phonetic:"",meaning:"A ‘second messenger’ involved in the action of adrenaline that activates protein kinase A.",example:"环磷酸腺苷（cAMP）",image_url:"",emoji:"🔬"},{word:"Deamination",phonetic:"",meaning:"Deaminase enzymes in the liver and, to a lesser extent, the kidneys remove an amino group (NH2) from a molecule as part of the urea cycle.",example:"脱氨基作用",image_url:"",emoji:"🔬"},{word:"Dipstick",phonetic:"",meaning:"A device which can be used for chemical testing or to measure liquid volume.",example:"检测试纸",image_url:"",emoji:"🔬"},{word:"Distal convoluted tubule (DCT)",phonetic:"",meaning:"The twisted region of the nephron between the loop of Henle and the collecting duct that alters the concentration of water and salts reabsorbed. Its permeability to water is altered by ADH.",example:"远曲小管（DCT）",image_url:"",emoji:"🔬"},{word:"Effector",phonetic:"",meaning:"An organ, tissue, or cell that produces a response to a stimulus.",example:"效应器",image_url:"",emoji:"🔬"},{word:"Efferent arteriole",phonetic:"",meaning:"The smaller diameter arteriole which carries the blood away from the glomerulus after ultrafiltration.",example:"出球小动脉",image_url:"",emoji:"🔬"},{word:"Endocrine system",phonetic:"",meaning:"A chemical messenger system. It consists of glands, which produce and secrete hormones into the bloodstream, and effectors.",example:"内分泌系统",image_url:"",emoji:"🔬"},{word:"Endoderm",phonetic:"",meaning:"A type of organism which can regulate its own body temperature without relying on external heat sources.",example:"内胚层",image_url:"",emoji:"🔬"},{word:"Enzyme cascade",phonetic:"",meaning:"A series of successive enzymatic reactions in which the product of one reaction serves as the substrate for the next.",example:"酶级联反应",image_url:"",emoji:"🔬"},{word:"Excretion",phonetic:"",meaning:"The process of removing waste products from an organism.",example:"排泄",image_url:"",emoji:"🔬"},{word:"Fibrous capsule",phonetic:"",meaning:"A tough layer that surrounds and protects the kidney. It consists of fibres, collagen and elastin.",example:"纤维囊",image_url:"",emoji:"🔬"},{word:"Glomerular filtrate",phonetic:"",meaning:"The fluid produced by ultrafiltration of the blood into the renal capsule. It contains water, glucose, mineral ions and urea.",example:"肾小球滤液",image_url:"",emoji:"🔬"},{word:"Glomerulus",phonetic:"",meaning:"The bundle of blood vessels at the beginning of a kidney nephron where ultrafiltration takes place.",example:"肾小球",image_url:"",emoji:"🔬"},{word:"Glucagon",phonetic:"",meaning:"A hormone secreted by alpha cells (α cells) of the Islets of Langerhans in the pancreas. It increases blood glucose concentration.",example:"胰高血糖素",image_url:"",emoji:"🔬"},{word:"Glucose oxidase",phonetic:"",meaning:"An enzyme which oxidises glucose to hydrogen peroxide. It is often used alongside peroxidase to determine oxygen concentration via a dipstick method.",example:"葡萄糖氧化酶",image_url:"",emoji:"🔬"},{word:"G-protein",phonetic:"",meaning:"A protein that serves as a ‘molecular switch’ inside cells. Activation of the G-protein in the control of blood concentration results in the stimulation of adenylyl cyclase.",example:"G蛋白",image_url:"",emoji:"🔬"},{word:"Guard cells",phonetic:"",meaning:"Cells that surround the stomata and change shape depending on water potential. They control the rate of transpiration by becoming turgid or flaccid, opening or closing the stomata.",example:"保卫细胞",image_url:"",emoji:"🔬"},{word:"Homeostasis",phonetic:"",meaning:"Maintaining a constant internal environment around an optimum despite external change.",example:"稳态（体内平衡）",image_url:"",emoji:"🔬"},{word:"Hypothalamus",phonetic:"",meaning:"The region of the brain that serves as the control centre for the autonomic nervous system. It is responsible for production of hormones, the regulation of the water potential of body fluids and the control of behavioural patterns.",example:"下丘脑",image_url:"",emoji:"🔬"},{word:"Insulin",phonetic:"",meaning:"A hormone secreted by beta cells (𝛽 cells) of the Islets of Langerhans in the pancreas that decreases blood glucose concentration.",example:"胰岛素",image_url:"",emoji:"🔬"},{word:"Islets of Langerhans",phonetic:"",meaning:"Regions of the pancreas which contain α and β cells.",example:"胰岛（朗格汉斯岛）",image_url:"",emoji:"🔬"},{word:"Ketones",phonetic:"",meaning:"Carbonyl compounds produced during beta-oxidation of fat in the liver. A high level of ketones in the blood may indicate diabetes.",example:"酮体",image_url:"",emoji:"🔬"},{word:"Kidney",phonetic:"",meaning:"Organ involved in blood filtration and urine excretion. It also produces some hormones.",example:"肾脏",image_url:"",emoji:"🔬"},{word:"Loop of Henle",phonetic:"",meaning:"A large hairpin shaped loop found in the kidney tubule used to regulate the water and salt concentration of the blood.",example:"亨利环（髓袢）",image_url:"",emoji:"🔬"},{word:"Medulla",phonetic:"",meaning:"The inner region of the kidney consisting of renal pyramids made up of nephrons.",example:"肾髓质",image_url:"",emoji:"🔬"},{word:"Negative feedback",phonetic:"",meaning:"The product of a process that counteracts change to maintain an equilibrium around a normal level.",example:"负反馈",image_url:"",emoji:"🔬"},{word:"Nephron",phonetic:"",meaning:"The basic functional unit of the kidney.",example:"肾单位",image_url:"",emoji:"🔬"},{word:"Osmoreceptor",phonetic:"",meaning:"A type of receptor found in the hypothalamus which can detect the water concentration of blood plasma to maintain an appropriate water balance in the body.",example:"渗透压感受器",image_url:"",emoji:"🔬"},{word:"Osmoregulation",phonetic:"",meaning:"The homeostatic regulation of the osmotic pressure of body fluids.",example:"渗透调节",image_url:"",emoji:"🔬"},{word:"Pancreas",phonetic:"",meaning:"An organ which has both exocrine and endocrine functions and is involved in both digestion and the homeostatic control of blood glucose levels.",example:"胰腺",image_url:"",emoji:"🔬"},{word:"Parasympathetic nervous system",phonetic:"",meaning:"A branch of the autonomic nervous system that is active under normal, resting conditions. It inhibits effectors, slowing down activity.",example:"副交感神经系统",image_url:"",emoji:"🔬"},{word:"Peripheral nervous system",phonetic:"",meaning:"Pairs of nerves that originate from the CNS and carry nerve impulses into and out of the CNS. It is divided into the sensory nervous system and motor nervous system.",example:"外周神经系统",image_url:"",emoji:"🔬"},{word:"Peroxidases",phonetic:"",meaning:"A group of enzymes which catalyse reactions when hydrogen peroxide is present.",example:"过氧化物酶",image_url:"",emoji:"🔬"},{word:"pH",phonetic:"",meaning:"A logarithmic scale used to measure the relative acidity/ alkalinity of a substance. It is calculated using the formula: pH = -log10[H+]",example:"pH值（酸碱度）",image_url:"",emoji:"🔬"},{word:"Pituitary gland",phonetic:"",meaning:"A small, hormone-producing gland located at the base of the brain. It is divided into two regions, the anterior pituitary and the posterior pituitary.",example:"垂体",image_url:"",emoji:"🔬"},{word:"Posterior pituitary gland",phonetic:"",meaning:"The region of the pituitary gland that stores and secretes hormones (such as ADH) produced by the hypothalamus.",example:"垂体后叶（神经垂体）",image_url:"",emoji:"🔬"},{word:"Protein kinase A",phonetic:"",meaning:"An enzyme involved in the control of blood glucose concentration that modifies other proteins by phosphorylating them. Its activity depends on cellular concentrations of cAMP.",example:"蛋白激酶A",image_url:"",emoji:"🔬"},{word:"Proximal convoluted tubule (PCT)",phonetic:"",meaning:"The twisted portion of the nephron between the renal capsule and the loop of Henle. Its walls consist of epithelial cells that are adapted for the reabsorption of glucose and water into the blood.",example:"近曲小管（PCT）",image_url:"",emoji:"🔬"},{word:"Receptor",phonetic:"",meaning:"A specialised structure that detects a specific type of stimulus.",example:"感受器（受体）",image_url:"",emoji:"🔬"},{word:"Renal arteries",phonetic:"",meaning:"Blood vessels that carry oxygenated blood to the kidneys.",example:"肾动脉",image_url:"",emoji:"🔬"},{word:"Renal pelvis",phonetic:"",meaning:"The central region of the kidney that serves as a funnel for the flow of urine into the ureter.",example:"肾盂",image_url:"",emoji:"🔬"},{word:"Renal veins",phonetic:"",meaning:"Blood vessels that drain the kidneys.",example:"肾静脉",image_url:"",emoji:"🔬"},{word:"Second messenger model",phonetic:"",meaning:"The mechanism by which a hormone (e.g. adrenaline or glucagon) has an effect inside a cell by triggering the production of a second messenger such as cAMP.",example:"第二信使模型",image_url:"",emoji:"🔬"},{word:"Selective reabsorption",phonetic:"",meaning:"The selective reuptake of useful substances (small molecules and ions) in the proximal convoluted tubule using membrane transport proteins.",example:"选择性重吸收",image_url:"",emoji:"🔬"},{word:"Somatic nervous system",phonetic:"",meaning:"A branch of the nervous system that carries impulses to the skeletal muscles. It controls voluntary activities.",example:"躯体神经系统",image_url:"",emoji:"🔬"},{word:"Stimulus",phonetic:"",meaning:"An internal or external change or factor which triggers a response.",example:"刺激",image_url:"",emoji:"🔬"},{word:"Stomata",phonetic:"",meaning:"Small pores found on the epidermis of leaves that can be opened or closed by guard cells to control the amount of water loss and gas exchange.",example:"气孔",image_url:"",emoji:"🔬"},{word:"Sympathetic nervous system",phonetic:"",meaning:"A branch of the autonomic nervous system that is active under stressful conditions. It stimulates effectors, speeding up activity.",example:"交感神经系统",image_url:"",emoji:"🔬"},{word:"Tissue fluid",phonetic:"",meaning:"A liquid formed when hydrostatic pressure at the arteriole end of a capillary bed forces fluid out into the surrounding tissue.",example:"组织液",image_url:"",emoji:"🔬"},{word:"Transpiration",phonetic:"",meaning:"Water loss from plant leaves and stems via diffusion and evaporation. The rate of transpiration is affected by light, temperature, humidity, air movement and soil-water availability.",example:"蒸腾作用",image_url:"",emoji:"🔬"},{word:"Ultrafiltration",phonetic:"",meaning:"The removal of small molecules, water and ions from the blood in the glomerulus of the kidney at high pressure.",example:"超滤作用",image_url:"",emoji:"🔬"},{word:"Urea",phonetic:"",meaning:"A diamide produced from ammonia when proteins are broken down.",example:"尿素",image_url:"",emoji:"🔬"},{word:"Urea cycle",phonetic:"",meaning:"The cycle of reactions responsible for producing urea from ammonia for detoxification and excretion.",example:"尿素循环",image_url:"",emoji:"🔬"},{word:"Ureter",phonetic:"",meaning:"A tube that carries urine to the bladder from the kidneys.",example:"输尿管",image_url:"",emoji:"🔬"},{word:"Urine",phonetic:"",meaning:"A waste liquid containing urea. It flows through the kidneys, which regulate its water content, and is stored in the bladder before excretion.",example:"尿液",image_url:"",emoji:"🔬"},{word:"Water potential",phonetic:"",meaning:"A measure of the tendency of water molecules to move from one area to another measured in kilopascals (kPa) and given the symbol Ψ.",example:"水势",image_url:"",emoji:"🔬"}]},{key:"caie-bio-alevel-topic15",name:"CAIE生物A-Level · Topic 15 控制与协调",description:"Control and Coordination · 61 个术语定义（A-Level 生物）",words:[{word:"Acetylcholine",phonetic:"",meaning:"A type of neurotransmitter that is used for communication between neurones.",example:"乙酰胆碱",image_url:"",emoji:"🔬"},{word:"Actin",phonetic:"",meaning:"A type of protein filament found in myofibrils. It forms thin filaments consisting of two long twisted chains.",example:"肌动蛋白",image_url:"",emoji:"🔬"},{word:"Actin-myosin binding site",phonetic:"",meaning:"A site on actin that is normally blocked by tropomyosin. During muscle contraction, it becomes exposed, allowing a myosin head to attach.",example:"肌动蛋白-肌球蛋白结合位点",image_url:"",emoji:"🔬"},{word:"Actin-myosin crossbridge",phonetic:"",meaning:"The cross-bridge formed when a myosin head attaches to the myosin binding site on an actin filament.",example:"肌动蛋白-肌球蛋白横桥",image_url:"",emoji:"🔬"},{word:"Action potential",phonetic:"",meaning:"The temporary change in electrical potential across the membrane of an axon in response to the transmission of a nerve impulse.",example:"动作电位",image_url:"",emoji:"🔬"},{word:"All-or-nothing principle",phonetic:"",meaning:"The principle that describes how any generator potential which reaches or exceeds the threshold potential will produce an action potential of equal magnitude.",example:"全或无定律",image_url:"",emoji:"🔬"},{word:"Anisotropic (A) bands",phonetic:"",meaning:"The darker bands in a myofibril, which consist of overlapping actin and myosin filaments.",example:"各向异性（A）带",image_url:"",emoji:"🔬"},{word:"Antidiuretic hormone (ADH)",phonetic:"",meaning:"A hormone released from the posterior pituitary gland that increases the reabsorption of water in the kidney tubules.",example:"抗利尿激素（ADH）",image_url:"",emoji:"🔬"},{word:"Autonomic nervous system",phonetic:"",meaning:"A branch of the nervous system that carries nerve impulses to muscles and glands. It controls involuntary activities and has two divisions: the sympathetic nervous system and the parasympathetic nervous system.",example:"自主神经系统",image_url:"",emoji:"🔬"},{word:"Auxins",phonetic:"",meaning:"A class of plant hormones that control cell elongation, produce tropisms, prevent abscission, maintain apical dominance and stimulate the production of ethene.",example:"生长素",image_url:"",emoji:"🔬"},{word:"Central nervous system (CNS)",phonetic:"",meaning:"The brain and spinal cord.",example:"中枢神经系统（CNS）",image_url:"",emoji:"🔬"},{word:"Chemoreceptor cell",phonetic:"",meaning:"A specialised sensory receptor cell that transduces a chemical to produce a biological signal. Chemoreceptor cells are found on the tongue.",example:"化学感受器细胞",image_url:"",emoji:"🔬"},{word:"Cholinergic synapse",phonetic:"",meaning:"A synapse which uses the neurotransmitter acetylcholine.",example:"胆碱能突触",image_url:"",emoji:"🔬"},{word:"Dendron",phonetic:"",meaning:"An extension from a nerve cell that carries impulses towards the cell body.",example:"树突",image_url:"",emoji:"🔬"},{word:"Endocrine system",phonetic:"",meaning:"A chemical messenger system. It consists of glands, which produce and secrete hormones into the bloodstream, and effectors.",example:"内分泌系统",image_url:"",emoji:"🔬"},{word:"Gibberellins",phonetic:"",meaning:"Plant hormones that control stem elongation, trigger the growth of the pollen tube during fertilisation and stimulate the mobilisation of food storage reserves during seed germination.",example:"赤霉素",image_url:"",emoji:"🔬"},{word:"Glucagon",phonetic:"",meaning:"A hormone secreted by alpha cells (α cells) of the Islets of Langerhans in the pancreas. It increases blood glucose concentration.",example:"胰高血糖素",image_url:"",emoji:"🔬"},{word:"Hormones",phonetic:"",meaning:"Cell signalling molecules produced by endocrine glands and released into the blood. They travel to target cells and bind to specific receptors, initiating a response. The effects of hormones are usually long-lasting.",example:"激素",image_url:"",emoji:"🔬"},{word:"Hyperpolarisation",phonetic:"",meaning:"The drop in membrane potential below the resting potential after repolarization due to open potassium ion channels.",example:"超极化",image_url:"",emoji:"🔬"},{word:"H-zone",phonetic:"",meaning:"The lighter region in the centre of each A band.",example:"H带",image_url:"",emoji:"🔬"},{word:"Insulin",phonetic:"",meaning:"A hormone secreted by beta cells (𝛽 cells) of the Islets of Langerhans in the pancreas that decreases blood glucose concentration.",example:"胰岛素",image_url:"",emoji:"🔬"},{word:"Intermediate neurone",phonetic:"",meaning:"A neurone that links a sensory neurone to a motor neurone.",example:"中间神经元",image_url:"",emoji:"🔬"},{word:"Isotropic (I) bands",phonetic:"",meaning:"The lighter bands in a myofibril which consist of actin filaments only.",example:"各向同性（I）带",image_url:"",emoji:"🔬"},{word:"Motor neurone",phonetic:"",meaning:"A neurone that carries nerve impulses from the CNS to the effectors.",example:"运动神经元",image_url:"",emoji:"🔬"},{word:"Myelination",phonetic:"",meaning:"The formation of a myelin sheath around nerve cells by Schwann Cells.",example:"髓鞘化",image_url:"",emoji:"🔬"},{word:"Myelin sheath",phonetic:"",meaning:"An electrically insulating layer consisting of the membranes of Schwann cells. It increases the speed of nerve impulses.",example:"髓鞘",image_url:"",emoji:"🔬"},{word:"Myofibrils",phonetic:"",meaning:"Tiny contractile muscle fibres which group together. Numerous myofibril bundles constitute muscles. Myofibrils consist of two protein filaments: actin and myosin.",example:"肌原纤维",image_url:"",emoji:"🔬"},{word:"Myosin",phonetic:"",meaning:"A type of protein filament found in myofibrils. It forms thick filaments, consisting of long tails with bulbous heads, positioned to the side.",example:"肌球蛋白",image_url:"",emoji:"🔬"},{word:"Neuromuscular junction",phonetic:"",meaning:"An excitatory synapse formed between a motor neurone and a muscle fibre that uses the neurotransmitter, acetylcholine.",example:"神经肌肉接头",image_url:"",emoji:"🔬"},{word:"Neurotransmitters",phonetic:"",meaning:"Chemicals that are used for communication between neurones and their target cells. Neurotransmitters are stored in synaptic vesicles in the presynaptic neurone and released into the synaptic cleft.",example:"神经递质",image_url:"",emoji:"🔬"},{word:"Nodes of Ranvier",phonetic:"",meaning:"Unmyelinated sections of nerve cells which allow for the propagation of an action potential due to their many ion channels..",example:"朗飞结",image_url:"",emoji:"🔬"},{word:"Parasympathetic nervous system",phonetic:"",meaning:"A branch of the autonomic nervous system that is active under normal, resting conditions. It inhibits effectors, slowing down activity.",example:"副交感神经系统",image_url:"",emoji:"🔬"},{word:"Peripheral nervous system",phonetic:"",meaning:"Pairs of nerves that originate from the CNS and carry nerve impulses into and out of the CNS. It is divided into the sensory nervous system and motor nervous system.",example:"外周神经系统",image_url:"",emoji:"🔬"},{word:"Phototropism",phonetic:"",meaning:"A plant’s growth response to light.",example:"向光性",image_url:"",emoji:"🔬"},{word:"Positive tropism",phonetic:"",meaning:"The growth of a plant towards a stimulus.",example:"正向性",image_url:"",emoji:"🔬"},{word:"Postsynaptic neurone",phonetic:"",meaning:"The neurone after the synapse which contains specific receptor proteins on its membrane, complementary to the neurotransmitter.",example:"突触后神经元",image_url:"",emoji:"🔬"},{word:"Presynaptic neurone",phonetic:"",meaning:"The neurone before the synapse which releases neurotransmitters from synaptic vesicles into the synaptic cleft.",example:"突触前神经元",image_url:"",emoji:"🔬"},{word:"Receptor cells",phonetic:"",meaning:"Specialised cells which contain structures that detect a specific type of stimulus.",example:"感受器细胞",image_url:"",emoji:"🔬"},{word:"Refractory period",phonetic:"",meaning:"The time period after an action potential during which further action potentials are prevented. This ensures that action potentials can only be propagated in one direction. It limits the frequency of action potentials and ensures nervous impulses are discrete.",example:"不应期",image_url:"",emoji:"🔬"},{word:"Relay neurone",phonetic:"",meaning:"A neurone located in the spinal cord that links the sensory neurone to the motor neurone.",example:"中继神经元",image_url:"",emoji:"🔬"},{word:"Resting potential",phonetic:"",meaning:"The potential difference across the cell membrane of a neurone at rest which is typically between -60 and -70 millivolts (mV).",example:"静息电位",image_url:"",emoji:"🔬"},{word:"Saltatory conduction",phonetic:"",meaning:"The setting up of localised circuits between nodes of Ranvier which allows for the rapid propagation of an action potential.",example:"跳跃式传导",image_url:"",emoji:"🔬"},{word:"Sarcomere",phonetic:"",meaning:"Each repeating unit of striations between adjacent Z-lines.",example:"肌节",image_url:"",emoji:"🔬"},{word:"Sarcoplasm",phonetic:"",meaning:"The cytoplasm shared by muscle fibres. It consists of a high concentration of mitochondria and endoplasmic reticulum.",example:"肌质（肌浆）",image_url:"",emoji:"🔬"},{word:"Sarcoplasmic reticulum",phonetic:"",meaning:"A membrane-bound structure in muscle cells that stores calcium ions.",example:"肌质网",image_url:"",emoji:"🔬"},{word:"Schwann cells",phonetic:"",meaning:"Cells that form the myelin sheath around nerve cells in the peripheral nervous system.",example:"施万细胞",image_url:"",emoji:"🔬"},{word:"Sensory neurone",phonetic:"",meaning:"A neurone that carries nerve impulses from the receptors to the CNS.",example:"感觉神经元",image_url:"",emoji:"🔬"},{word:"Skeletal muscle",phonetic:"",meaning:"A voluntary muscle responsible for movement. It makes up the majority of body muscle and is attached to the skeleton by tendons.",example:"骨骼肌",image_url:"",emoji:"🔬"},{word:"Sliding filament model",phonetic:"",meaning:"The mechanism by which a muscle contracts. During contraction, myosin filaments pull actin filaments to the centre of the sarcomere. The actin filaments slide along the myosin filaments. The sarcomere is shortened and the muscle length is reduced.",example:"肌丝滑行学说",image_url:"",emoji:"🔬"},{word:"Somatic nervous system",phonetic:"",meaning:"A branch of the nervous system that carries impulses to the skeletal muscles. It controls voluntary activities.",example:"躯体神经系统",image_url:"",emoji:"🔬"},{word:"Stimulus",phonetic:"",meaning:"An internal or external change which triggers a response.",example:"刺激",image_url:"",emoji:"🔬"},{word:"Striated muscle",phonetic:"",meaning:"Muscle tissue consisting of sarcomeres.",example:"横纹肌",image_url:"",emoji:"🔬"},{word:"Sympathetic nervous system",phonetic:"",meaning:"A branch of the autonomic nervous system that is active under stressful conditions. It stimulates effectors, speeding up activity.",example:"交感神经系统",image_url:"",emoji:"🔬"},{word:"Synapse",phonetic:"",meaning:"The junction between two nerve cells or a nerve cell and an effector.",example:"突触",image_url:"",emoji:"🔬"},{word:"Synaptic vesicles",phonetic:"",meaning:"Secretory vesicles located in the presynaptic neurone that store neurotransmitters. Upon fusion with the presynaptic membrane, their contents are released into the synaptic cleft.",example:"突触小泡",image_url:"",emoji:"🔬"},{word:"Transverse system tubules (T-tubules)",phonetic:"",meaning:"Tubules which run through striated muscle fibres and transmit the action potential.",example:"横管（T管）",image_url:"",emoji:"🔬"},{word:"Tropism",phonetic:"",meaning:"The growth response of a plant to a directional stimulus.",example:"向性",image_url:"",emoji:"🔬"},{word:"Tropomyosin",phonetic:"",meaning:"A protein found in muscles that forms a fibrous strand wrapped around an actin filament.",example:"原肌球蛋白",image_url:"",emoji:"🔬"},{word:"Troponin",phonetic:"",meaning:"A protein which regulates the position of tropomyosin. When calcium ions bind to troponin, it changes conformation and causes tropomyosin to move.",example:"肌钙蛋白",image_url:"",emoji:"🔬"},{word:"Venus fly trap",phonetic:"",meaning:"A plant which responds rapidly by snapping shut when hairs on the lobes of modified leaves are stimulated twice within 20 seconds.",example:"捕蝇草",image_url:"",emoji:"🔬"},{word:"Z-line",phonetic:"",meaning:"The line in the centre of each I band.",example:"Z线",image_url:"",emoji:"🔬"}]},{key:"caie-bio-alevel-topic16",name:"CAIE生物A-Level · Topic 16 遗传与变异",description:"Inherited Change · 57 个术语定义（A-Level 生物）",words:[{word:"Albinism",phonetic:"",meaning:"An autosomal recessive condition due to mutations of the tyrosinase (TYR) gene. It is characterised by lack of pigment in the skin, eyes and hair.",example:"白化病",image_url:"",emoji:"🔬"},{word:"Allele",phonetic:"",meaning:"A version of a gene.",example:"等位基因",image_url:"",emoji:"🔬"},{word:"Anaphase I",phonetic:"",meaning:"The third stage of meiosis where the chromosomes that make up the bivalent are pulled apart to the poles of the cell by the spindle fibres.",example:"减数第一次分裂后期",image_url:"",emoji:"🔬"},{word:"Anaphase II",phonetic:"",meaning:"The seventh stage of meiosis where the chromatids are pulled apart to opposite poles of the cell.",example:"减数第二次分裂后期",image_url:"",emoji:"🔬"},{word:"Autosomal linkage",phonetic:"",meaning:"When two or more genes are positioned on the same autosome. They are unlikely to be separated by crossing over during meiosis so are often inherited together.",example:"常染色体连锁",image_url:"",emoji:"🔬"},{word:"Chi-squared (X2) test",phonetic:"",meaning:"A statistical test used to determine whether a pattern of inheritance is statistically significant.",example:"卡方检验",image_url:"",emoji:"🔬"},{word:"Codominance",phonetic:"",meaning:"When both alleles for a gene in a heterozygous organism equally contribute to the phenotype.",example:"共显性",image_url:"",emoji:"🔬"},{word:"Crossing over",phonetic:"",meaning:"The exchange of genetic material between two chromosomes in a bivalent.",example:"交叉互换",image_url:"",emoji:"🔬"},{word:"Degrees of freedom (X2 test)",phonetic:"",meaning:"The number of categories minus one.",example:"自由度（卡方检验）",image_url:"",emoji:"🔬"},{word:"DELLA protein repressors",phonetic:"",meaning:"Negative regulators of gibberellin.",example:"DELLA蛋白阻遏物",image_url:"",emoji:"🔬"},{word:"Dihybrid inheritance",phonetic:"",meaning:"The determination of a trait by the inheritance of two genes.",example:"双因子遗传",image_url:"",emoji:"🔬"},{word:"Diploid (2n)",phonetic:"",meaning:"Cells with two copies of each chromosome.",example:"二倍体",image_url:"",emoji:"🔬"},{word:"Dominant allele",phonetic:"",meaning:"Describes an allele that is always expressed. Dominant alleles are represented by a capital letter in genetic crosses.",example:"显性等位基因",image_url:"",emoji:"🔬"},{word:"Embryo sac (plants)",phonetic:"",meaning:"The female gametophyte in flowering plants. It is formed when the haploid megaspore nucleus divides.",example:"胚囊（植物）",image_url:"",emoji:"🔬"},{word:"Epistasis",phonetic:"",meaning:"Describes a relationship between genes at different loci, where the allele of one gene affects the expression of a different gene.",example:"上位效应",image_url:"",emoji:"🔬"},{word:"F1",phonetic:"",meaning:"The first generation of offspring from a genetic cross.",example:"子一代",image_url:"",emoji:"🔬"},{word:"F2",phonetic:"",meaning:"The offspring produced when F1 individuals reproduce with one another.",example:"子二代",image_url:"",emoji:"🔬"},{word:"Fertilisation",phonetic:"",meaning:"The fusion of male and female gametes. This is random and produces genetically different individuals.",example:"受精",image_url:"",emoji:"🔬"},{word:"Gametes",phonetic:"",meaning:"Sex cells that have a haploid nucleus and are produced through meioisis.",example:"配子",image_url:"",emoji:"🔬"},{word:"Gene",phonetic:"",meaning:"A length of DNA on a chromosome that codes for the production of one or more polypeptide chains and functional RNA.",example:"基因",image_url:"",emoji:"🔬"},{word:"Gene expression",phonetic:"",meaning:"Some genes in cells are ‘switched on’ so that their corresponding protein is produced, whereas other genes are silenced.",example:"基因表达",image_url:"",emoji:"🔬"},{word:"Genetic cross",phonetic:"",meaning:"Individuals of a species are bred. The ratio of phenotypes present in their offspring can be linked to the genotype of the parent.",example:"遗传杂交",image_url:"",emoji:"🔬"},{word:"Genetic variation",phonetic:"",meaning:"Differences in the DNA sequence of individuals, including individuals of the same species.",example:"遗传变异",image_url:"",emoji:"🔬"},{word:"Genotype",phonetic:"",meaning:"An organism’s genetic composition. Describes all alleles.",example:"基因型",image_url:"",emoji:"🔬"},{word:"Gibberellins",phonetic:"",meaning:"Plant hormones that control stem elongation, trigger the growth of the pollen tube during fertilisation and stimulate the mobilisation of food storage reserves during seed germination.",example:"赤霉素",image_url:"",emoji:"🔬"},{word:"Haemophilia",phonetic:"",meaning:"A sex-linked genetic condition caused by a mutation of the factor VIII (F8) gene on the X chromosome. This disrupts the body’s ability to form clots.",example:"血友病",image_url:"",emoji:"🔬"},{word:"Haploid (n)",phonetic:"",meaning:"Cells with only one copy of each chromosome.",example:"单倍体",image_url:"",emoji:"🔬"},{word:"Heterozygous",phonetic:"",meaning:"When someone has two different alleles of a gene e.g. Ff.",example:"杂合子",image_url:"",emoji:"🔬"},{word:"Homologous chromosomes",phonetic:"",meaning:"Two chromosomes with similar gene loci but different alleles, one inherited from each parent.",example:"同源染色体",image_url:"",emoji:"🔬"},{word:"Homozygous",phonetic:"",meaning:"When someone has two identical alleles of a gene e.g. ff.",example:"纯合子",image_url:"",emoji:"🔬"},{word:"Huntington’s disease",phonetic:"",meaning:"A genetic condition caused by a mutation (CAG trisomy expansion) of the huntingtin (HTT) gene. This results in progressive death of nerve cells in the brain.",example:"亨廷顿病",image_url:"",emoji:"🔬"},{word:"Independent assortment",phonetic:"",meaning:"A source of variation in meiosis where the bivalent chromosomes can line up either way around on the metaphase plate.",example:"自由组合",image_url:"",emoji:"🔬"},{word:"Inducible enzyme",phonetic:"",meaning:"An enzyme which is only expressed when cells are exposed to its specific substrate.",example:"诱导酶",image_url:"",emoji:"🔬"},{word:"Lac operon",phonetic:"",meaning:"A group of three structural genes, lacZ, lacY and lacA, that are required for the metabolism of lactose.",example:"乳糖操纵子",image_url:"",emoji:"🔬"},{word:"Le allele",phonetic:"",meaning:"A dominant allele that codes for a functional enzyme in the gibberellin synthesis pathway. If a plant possesses the Le allele, gibberellin is active and the plant grows tall.",example:"Le等位基因",image_url:"",emoji:"🔬"},{word:"le allele",phonetic:"",meaning:"A recessive allele that codes for a non-functional enzyme in the gibberellin synthesis pathway. If a plant possesses two copies of the le allele, gibberellin is not produced and the plant grows dwarf.",example:"le等位基因（隐性，矮茎）",image_url:"",emoji:"🔬"},{word:"Locus",phonetic:"",meaning:"A position on a chromosome.",example:"基因座",image_url:"",emoji:"🔬"},{word:"Meiosis",phonetic:"",meaning:"A type of cell division used to produce gametes that produces four genetically different haploid daughter cells from one parent cell.",example:"减数分裂",image_url:"",emoji:"🔬"},{word:"Metaphase I",phonetic:"",meaning:"The second stage of meiosis where the bivalent chromosomes align along the metaphase plate and independent assortment occurs.",example:"减数第一次分裂中期",image_url:"",emoji:"🔬"},{word:"Metaphase II",phonetic:"",meaning:"The sixth stage of meiosis where the recombinant chromosomes align on the metaphase plate.",example:"减数第二次分裂中期",image_url:"",emoji:"🔬"},{word:"Monohybrid cross",phonetic:"",meaning:"A genetic cross in which only one gene is studied.",example:"单因子杂交",image_url:"",emoji:"🔬"},{word:"Phenotype",phonetic:"",meaning:"An organism’s observable characteristics. Due to interactions of the genotype and the environment.",example:"表现型",image_url:"",emoji:"🔬"},{word:"Prophase I",phonetic:"",meaning:"The first stage of meiosis where the nuclear envelope breaks down, the spindle fibres form and the chromosomes condense and form bivalents. This is the stage of meiosis where crossing over occurs.",example:"减数第一次分裂前期",image_url:"",emoji:"🔬"},{word:"Prophase II",phonetic:"",meaning:"The fifth stage of meiosis where the nuclear envelope breaks down, the spindle fibres form and the chromosomes condense.",example:"减数第二次分裂前期",image_url:"",emoji:"🔬"},{word:"Punnett square",phonetic:"",meaning:"A square diagram used to predict the possible genotypes and phenotypes of an offspring and the probability of each when two individuals breed.",example:"庞尼特方格",image_url:"",emoji:"🔬"},{word:"Recessive allele",phonetic:"",meaning:"Describes an allele that is only expressed in the absence of a dominant allele. Represented by a small letter.",example:"隐性等位基因",image_url:"",emoji:"🔬"},{word:"Regulatory gene",phonetic:"",meaning:"A gene that codes for the production of proteins involved in DNA regulation. The expression of regulatory genes is influenced by internal and external stimuli.",example:"调节基因",image_url:"",emoji:"🔬"},{word:"Repressible enzyme",phonetic:"",meaning:"Operons for repressible enzymes are switched on under normal conditions but can be repressed in response to a stimulus.",example:"阻遏酶",image_url:"",emoji:"🔬"},{word:"Sex linkage",phonetic:"",meaning:"The presence of a gene on an X or Y chromosome.",example:"性连锁",image_url:"",emoji:"🔬"},{word:"Sexual reproduction",phonetic:"",meaning:"Reproduction which involves the fusion of male and female gametes. It introduces genetic variation.",example:"有性生殖",image_url:"",emoji:"🔬"},{word:"Sickle cell anaemia",phonetic:"",meaning:"A disease characterised by hook-shaped red blood cells. A missense point mutation of GAG to GTG in the HbA (normal) allele for the β-globin polypeptide results in the HbS (sickle cell) allele of the gene.",example:"镰状细胞贫血",image_url:"",emoji:"🔬"},{word:"Structural gene",phonetic:"",meaning:"A gene that codes for the production of proteins or enzymes that are not involved in DNA regulation.",example:"结构基因",image_url:"",emoji:"🔬"},{word:"Telophase I",phonetic:"",meaning:"The fourth stage of meiosis where the nuclear envelopes reform around the separated chromosomes and they uncoil.",example:"减数第一次分裂末期",image_url:"",emoji:"🔬"},{word:"Telophase II",phonetic:"",meaning:"The final stage in meiosis where the nuclear envelopes reform around the separated chromatids (now called chromosomes) and they uncoil.",example:"减数第二次分裂末期",image_url:"",emoji:"🔬"},{word:"Test cross",phonetic:"",meaning:"An individual with the dominant phenotype is bred with an individual with the recessive phenotype (homozygous recessive genotype). The ratio of phenotypes present in the offspring indicates whether the dominant individual is homozygous or heterozygous for that allele.",example:"测交",image_url:"",emoji:"🔬"},{word:"Transcription factors",phonetic:"",meaning:"Proteins that help to switch genes ‘on’ or ‘off’ by controlling the binding of RNA polymerase to DNA.",example:"转录因子",image_url:"",emoji:"🔬"},{word:"Tyrosinase",phonetic:"",meaning:"An enzyme that catalyses the production of melanin from tyrosine by oxidation.",example:"酪氨酸酶",image_url:"",emoji:"🔬"}]},{key:"caie-bio-alevel-topic17",name:"CAIE生物A-Level · Topic 17 选择与进化",description:"Selection and Evolution · 24 个术语定义（A-Level 生物）",words:[{word:"Allopatric speciation",phonetic:"",meaning:"A form of speciation that occurs when two populations become geographically isolated due to a physical barrier.",example:"异域物种形成",image_url:"",emoji:"🔬"},{word:"Antibiotic-resistant bacteria",phonetic:"",meaning:"Bacteria that mutate to become resistant to an antibiotic, survive and reproduce very rapidly, passing on their antibiotic resistance.",example:"抗生素抗性细菌",image_url:"",emoji:"🔬"},{word:"Artificial selection",phonetic:"",meaning:"See ‘selective breeding’.",example:"人工选择",image_url:"",emoji:"🔬"},{word:"Climate change",phonetic:"",meaning:"The gradual change in regional and global climate patterns attributed to increasing atmospheric levels of greenhouse gases (e.g. carbon dioxide, methane gas).",example:"气候变化",image_url:"",emoji:"🔬"},{word:"Competition",phonetic:"",meaning:"When different organisms compete for the same resources (e.g. light, water, mates, territory) in an ecosystem. This limits population sizes.",example:"竞争",image_url:"",emoji:"🔬"},{word:"Continuous variation",phonetic:"",meaning:"A type of variation that cannot be categorised e.g. skin colour, height. It produces a continuous range in which a characteristic can take any value. Multiple genes influence continuous variation.",example:"连续变异",image_url:"",emoji:"🔬"},{word:"Directional selection",phonetic:"",meaning:"A type of selection that favours one extreme phenotype and selects against all other phenotypes.",example:"定向选择",image_url:"",emoji:"🔬"},{word:"Discontinuous variation",phonetic:"",meaning:"A type of variation that can be categorised e.g. blood group. A characteristic can only appear in discrete values. One or two genes influence discontinuous variation.",example:"不连续变异",image_url:"",emoji:"🔬"},{word:"Disruptive selection",phonetic:"",meaning:"A type of selection that favours individuals with extreme phenotypes and selects against those with phenotypes close to the mean.",example:"分裂选择",image_url:"",emoji:"🔬"},{word:"Evolution",phonetic:"",meaning:"The gradual change in the allele frequencies within a population over time. Occurs due to natural selection.",example:"进化",image_url:"",emoji:"🔬"},{word:"Founder effect",phonetic:"",meaning:"A type of genetic drift in which a few individuals of a species break off from the population and form a new colony. This results in smaller gene pools and an increased frequency of rare alleles.",example:"奠基者效应",image_url:"",emoji:"🔬"},{word:"Gene pool",phonetic:"",meaning:"All of the different versions of genes (alleles) in the individuals that make up a population.",example:"基因库",image_url:"",emoji:"🔬"},{word:"Genetic bottleneck",phonetic:"",meaning:"A drastic reduction in population size leading to reduced genetic diversity within a population.",example:"遗传瓶颈",image_url:"",emoji:"🔬"},{word:"Genetic drift",phonetic:"",meaning:"Random variations in allele frequencies in small populations, due to mutations.",example:"遗传漂变",image_url:"",emoji:"🔬"},{word:"Hardy–Weinberg principle",phonetic:"",meaning:"A model that predicts that the ratio of dominant and recessive alleles in a population will remain constant between generations if the following five conditions are met: no new mutations; no natural selection; no migration; large population; and random mating. It provides a formula for calculating the frequencies of alleles: p2 + 2pq + q2 = 1.0 where p is the frequency of the dominant allele, and q is the frequency of the recessive allele.",example:"哈迪-温伯格原理",image_url:"",emoji:"🔬"},{word:"Inbreeding",phonetic:"",meaning:"The formation of offspring from the breeding of closely related individuals.",example:"近亲繁殖",image_url:"",emoji:"🔬"},{word:"Natural selection",phonetic:"",meaning:"The process by which the frequency of beneficial alleles gradually increases in a population’s gene pool over time. This theory was developed by Charles Darwin.",example:"自然选择",image_url:"",emoji:"🔬"},{word:"Selection pressures",phonetic:"",meaning:"Factors that affect an organism’s ability to survive in an environment e.g. disease, prey, competitors, water availability.",example:"选择压力",image_url:"",emoji:"🔬"},{word:"Selective breeding",phonetic:"",meaning:"The process by which humans artificially select organisms with desirable characteristics and breed them to produce offspring with desirable phenotypes. Selective breeding may also be referred to as ‘artificial selection’.",example:"选择育种",image_url:"",emoji:"🔬"},{word:"Speciation",phonetic:"",meaning:"The formation of new species due to the evolution of two reproductively separated populations. Two forms: allopatric and sympatric speciation.",example:"物种形成",image_url:"",emoji:"🔬"},{word:"Stabilising selection",phonetic:"",meaning:"A type of selection that favours individuals with phenotypes close to the mean (average) and selects against extreme phenotypes.",example:"稳定选择",image_url:"",emoji:"🔬"},{word:"Sympatric speciation",phonetic:"",meaning:"A form of speciation that occurs when two populations within the same area become reproductively isolated.",example:"同域物种形成",image_url:"",emoji:"🔬"},{word:"T-test",phonetic:"",meaning:"A statistical test used to determine whether there is a statistically significant difference between the means of two data sets that show normal distribution. A paired t-test compares means from two different samples. An unpaired t-test compares means from the same sample.",example:"t检验",image_url:"",emoji:"🔬"},{word:"Variation",phonetic:"",meaning:"The differences between individuals due to genes, the environment or a combination of both.",example:"变异",image_url:"",emoji:"🔬"}]},{key:"caie-bio-alevel-topic18",name:"CAIE生物A-Level · Topic 18 生物多样性、分类与保护",description:"Biodiversity, Classification and Conservation · 48 个术语定义（A-Level 生物）",words:[{word:"Abiotic factors",phonetic:"",meaning:"The non-living aspects of an ecosystem e.g. light, temperature, water availability, oxygen availability and soil pH.",example:"非生物因素",image_url:"",emoji:"🔬"},{word:"Abundance",phonetic:"",meaning:"The number of individuals per species in a specific area at any given time.",example:"多度",image_url:"",emoji:"🔬"},{word:"Alien species",phonetic:"",meaning:"A species that is not native to an ecosystem. It may be introduced deliberately or accidentally into the environment.",example:"外来物种",image_url:"",emoji:"🔬"},{word:"Animalia",phonetic:"",meaning:"One of the Kingdoms of living organisms. Members are multicellular eukaryotes without cell walls.",example:"动物界",image_url:"",emoji:"🔬"},{word:"Archaea",phonetic:"",meaning:"One of the Domains of living organisms. Members are single-celled prokaryotes with ether-linked cell walls.",example:"古菌域",image_url:"",emoji:"🔬"},{word:"Bacteria",phonetic:"",meaning:"One of the domains of living organisms. Members are prokaryotes with ester-linked cell walls.",example:"细菌域",image_url:"",emoji:"🔬"},{word:"Belt transect",phonetic:"",meaning:"A line along a sampled area upon which quadrats are placed at intervals to determine the abundance and distribution of organisms in an ecosystem.",example:"带状样方",image_url:"",emoji:"🔬"},{word:"Biodiversity",phonetic:"",meaning:"The variety of genes, species and habitats within ecosystems or habitats.",example:"生物多样性",image_url:"",emoji:"🔬"},{word:"Biological species concept",phonetic:"",meaning:"Defines a species as a group of organisms whose members can interbreed to produce fertile offspring.",example:"生物学物种概念",image_url:"",emoji:"🔬"},{word:"Biotic factors",phonetic:"",meaning:"The living components of an ecosystem e.g. food availability, pathogens, predators and other species.",example:"生物因素",image_url:"",emoji:"🔬"},{word:"Classification",phonetic:"",meaning:"The process of grouping organisms based on their phylogenetic characteristics or evolutionary heritage.",example:"分类",image_url:"",emoji:"🔬"},{word:"Climate change",phonetic:"",meaning:"Long-term changes in usual weather and temperature patterns.",example:"气候变化",image_url:"",emoji:"🔬"},{word:"Competition",phonetic:"",meaning:"When different organisms compete for the same resources (e.g. light, water, mates, territory) in an ecosystem. This limits population sizes.",example:"竞争",image_url:"",emoji:"🔬"},{word:"Conservation",phonetic:"",meaning:"The maintenance of ecosystems and biodiversity by humans in order to preserve the Earth’s resources. The conservation of species requires the preservation of gene pools.",example:"保护（生态保护）",image_url:"",emoji:"🔬"},{word:"Convention on International Trade in Endangered Species of Wild Fauna and Flora (CITES)",phonetic:"",meaning:"A treaty that regulates the trade of plants and wild animals across international borders.",example:"《濒危野生动植物种国际贸易公约》(CITES)",image_url:"",emoji:"🔬"},{word:"Culling",phonetic:"",meaning:"Separating organisms based on whether they have desirable characteristics. Organisms with undesirable characteristics may be killed. May serve as a method of animal population control, including in conservation efforts.",example:"选择性淘汰",image_url:"",emoji:"🔬"},{word:"Distribution",phonetic:"",meaning:"The spread of living organisms in an ecosystem.",example:"分布",image_url:"",emoji:"🔬"},{word:"DNA virus",phonetic:"",meaning:"A virus whose genetic material is DNA. This group is subdivided according to whether the DNA is single-stranded or double-stranded.",example:"DNA病毒",image_url:"",emoji:"🔬"},{word:"Domain",phonetic:"",meaning:"The highest taxonomic rank. It is the broadest classification of living organisms.",example:"域",image_url:"",emoji:"🔬"},{word:"Ecological species concept",phonetic:"",meaning:"Defines a species as a group of organisms that are adapted to a particular niche.",example:"生态学物种概念",image_url:"",emoji:"🔬"},{word:"Ecosystem",phonetic:"",meaning:"The community of organisms (biotic) and non-living (abiotic) components of an area and their interactions.",example:"生态系统",image_url:"",emoji:"🔬"},{word:"Embryo transfer",phonetic:"",meaning:"Implantation of embryos into a uterus during assisted reproduction e.g. IVF.",example:"胚胎移植",image_url:"",emoji:"🔬"},{word:"Eukarya",phonetic:"",meaning:"A Domain of living organisms. Members are eukaryotes - their cells have a nucleus which contains DNA.",example:"真核生物域",image_url:"",emoji:"🔬"},{word:"Frozen zoo",phonetic:"",meaning:"A collection of genetic material, such as DNA, gametes and tissues, extracted from organisms and preserved at very low temperatures.",example:"冷冻动物园",image_url:"",emoji:"🔬"},{word:"Fungi",phonetic:"",meaning:"A Kingdom of living organisms. Members are non-photosynthetic eukaryotes with chitin cell walls.",example:"真菌界",image_url:"",emoji:"🔬"},{word:"Habitat",phonetic:"",meaning:"The region where an organism normally lives.",example:"栖息地",image_url:"",emoji:"🔬"},{word:"International Union for Conservation of Nature (IUCN)",phonetic:"",meaning:"An international organisation that promotes the conservation of nature and sustainable use of natural resources through scientific research, management of field projects and implementation of legislation.",example:"世界自然保护联盟 (IUCN)",image_url:"",emoji:"🔬"},{word:"In vitro fertilisation (IVF)",phonetic:"",meaning:"An assisted reproduction technique which involves collecting male and female gametes, fusing them in the laboratory and stimulating embryo growth before embryo transfer.",example:"体外受精 (IVF)",image_url:"",emoji:"🔬"},{word:"Lincoln index",phonetic:"",meaning:"A statistical measure used to estimate population sizes of animal species. It is based on the mark-release-recapture method.",example:"林肯指数",image_url:"",emoji:"🔬"},{word:"Line transect",phonetic:"",meaning:"A line along a sampled area. The species touching the transect at regular intervals are recorded to determine the abundance and distribution of organisms in an ecosystem.",example:"样线",image_url:"",emoji:"🔬"},{word:"Mark-release-recapture",phonetic:"",meaning:"A method of estimating the population size of motile organisms. It involves capturing a sample of the population, marking them and releasing them. At a later date, another sample is captured and the number of marked individuals recorded. The population size can be estimated using the following equation:",example:"标记-释放-重捕法",image_url:"",emoji:"🔬"},{word:"Morphological species concept",phonetic:"",meaning:"Defines a species as a group of organisms that share similar physiology and appearance.",example:"形态学物种概念",image_url:"",emoji:"🔬"},{word:"Niche",phonetic:"",meaning:"Describes how an organism ‘fits’ into an ecosystem and its role in that environment.",example:"生态位",image_url:"",emoji:"🔬"},{word:"Nucleic acid",phonetic:"",meaning:"A polymer of nucleotides that stores genetic information, e.g. DNA or RNA.",example:"核酸",image_url:"",emoji:"🔬"},{word:"Pearson’s linear correlation",phonetic:"",meaning:"A statistical test which determines the strength of the linear correlation between two variables. A value of 1 indicates perfect positive correlation and -1 indicates perfect negative correlation.",example:"皮尔逊线性相关",image_url:"",emoji:"🔬"},{word:"Plantae",phonetic:"",meaning:"One of the Kingdoms of living organisms. Members are photosynthetic eukaryotes.",example:"植物界",image_url:"",emoji:"🔬"},{word:"Protoctista",phonetic:"",meaning:"One of the Kingdoms of living things. Members include any eukaryotic organism that is not a plant, animal or fungus.",example:"原生生物界",image_url:"",emoji:"🔬"},{word:"Quadrat",phonetic:"",meaning:"A square grid of a known area used in sampling to determine the abundance of organisms in a habitat. There are two types: point quadrats and frame quadrats.",example:"样方",image_url:"",emoji:"🔬"},{word:"Random sampling",phonetic:"",meaning:"A sampling technique used to avoid bias e.g. creating a square grid and generating random coordinates.",example:"随机取样",image_url:"",emoji:"🔬"},{word:"RNA virus",phonetic:"",meaning:"A virus whose genetic material is RNA. This group is subdivided according to whether the RNA is single-stranded or double-stranded.",example:"RNA病毒",image_url:"",emoji:"🔬"},{word:"Seed bank",phonetic:"",meaning:"A storage of seeds to preserve genetic material.",example:"种子库",image_url:"",emoji:"🔬"},{word:"Simpson’s Index of Diversity",phonetic:"",meaning:"A measure of biodiversity in a habitat which takes both species richness and species abundance into consideration. It can be calculated using the formula:",example:"辛普森多样性指数",image_url:"",emoji:"🔬"},{word:"Spearman’s rank correlation",phonetic:"",meaning:"A statistical test which determines the strength of the non-linear correlation between two variables.",example:"斯皮尔曼等级相关",image_url:"",emoji:"🔬"},{word:"Species",phonetic:"",meaning:"A group of organisms that can successfully reproduce with one another, producing fertile offspring.",example:"物种",image_url:"",emoji:"🔬"},{word:"Surrogacy",phonetic:"",meaning:"One female individual carries the offspring of another female.",example:"代孕",image_url:"",emoji:"🔬"},{word:"Taxonomic hierarchy",phonetic:"",meaning:"The non-overlapping classification of living organisms according to their common ancestors. There are smaller groups within larger groups. In order from the largest group to the smallest group: Domain, Kingdom, Phylum, Class, Order, Family, Genus, Species.",example:"分类阶层",image_url:"",emoji:"🔬"},{word:"Virus",phonetic:"",meaning:"A non-living microorganism that consists of genetic material surrounded by a protein husk.",example:"病毒",image_url:"",emoji:"🔬"},{word:"World Wide Fund for Nature (WWF)",phonetic:"",meaning:"An international non-governmental organisation committed to the preservation of wildlife and reduction of human effects on the environment.",example:"世界自然基金会 (WWF)",image_url:"",emoji:"🔬"}]},{key:"caie-bio-alevel-topic19",name:"CAIE生物A-Level · Topic 19 基因技术",description:"Genetic Technology · 32 个术语定义（A-Level 生物）",words:[{word:"Bioinformatics",phonetic:"",meaning:"The development of the computer tools and software required to organise and analyse unprocessed biological data.",example:"生物信息学",image_url:"",emoji:"🔬"},{word:"Bt maize",phonetic:"",meaning:"A variant of maize genetically engineered to produce its own insecticide, the Bt toxin, making it resistant to corn borers.",example:"Bt玉米",image_url:"",emoji:"🔬"},{word:"Cystic fibrosis",phonetic:"",meaning:"An autosomal recessive condition characterised by the production of thick, sticky mucus that causes lung infections and scarring.",example:"囊性纤维化",image_url:"",emoji:"🔬"},{word:"DNA ligase",phonetic:"",meaning:"An enzyme that joins the sugar-phosphate backbone of two DNA segments.",example:"DNA连接酶",image_url:"",emoji:"🔬"},{word:"DNA polymerase",phonetic:"",meaning:"An enzyme that synthesises a double-stranded molecule of DNA from a single template strand using complementary nucleotides.",example:"DNA聚合酶",image_url:"",emoji:"🔬"},{word:"Embryo biopsy",phonetic:"",meaning:"A few cells from an embryo can be extracted and screened for genetic diseases.",example:"胚胎活检",image_url:"",emoji:"🔬"},{word:"Gel electrophoresis",phonetic:"",meaning:"A type of chromatography that separates nucleic acid fragments or proteins by size using electric current.",example:"凝胶电泳",image_url:"",emoji:"🔬"},{word:"Gene editing",phonetic:"",meaning:"A type of genetic engineering that involves the deletion, insertion or replacement of DNA at particular sites in the genome.",example:"基因编辑",image_url:"",emoji:"🔬"},{word:"Gene therapy",phonetic:"",meaning:"A therapeutic technique in which a faulty allele is replaced with a functional allele in order to treat or prevent disease.",example:"基因治疗",image_url:"",emoji:"🔬"},{word:"Genetically modified organism (GMO)",phonetic:"",meaning:"An organism that has had its genome altered.",example:"转基因生物 (GMO)",image_url:"",emoji:"🔬"},{word:"Genetic engineering",phonetic:"",meaning:"The modification of the genome of an organism by the insertion of a desired gene from another organism. This enables the formation of organisms with beneficial characteristics.",example:"基因工程",image_url:"",emoji:"🔬"},{word:"Genetic screening",phonetic:"",meaning:"Testing individuals for specific genes or faulty alleles. This can be used to detect disorders (e.g. haemophilia, sickle cell disease, cystic fibrosis, Huntington’s disease) or to identify an increased risk of some cancers (e.g. breast cancer).",example:"基因筛查",image_url:"",emoji:"🔬"},{word:"Genome sequencing",phonetic:"",meaning:"Determining the entire DNA nucleotide base sequence of an organism.",example:"基因组测序",image_url:"",emoji:"🔬"},{word:"GM salmon",phonetic:"",meaning:"Genetically modified salmon. A gene that is inserted into fertilised eggs results in an increased appetite, enabling the fish to reach the desired market size rapidly.",example:"转基因三文鱼",image_url:"",emoji:"🔬"},{word:"Golden rice",phonetic:"",meaning:"A variety of rice genetically engineered to produce beta-carotene, a precursor of vitamin A.",example:"黄金大米",image_url:"",emoji:"🔬"},{word:"Haemophilia",phonetic:"",meaning:"A sex-linked genetic condition caused by a mutation of the factor VIII (F8) gene on the X chromosome. This disrupts the body’s ability to form clots.",example:"血友病",image_url:"",emoji:"🔬"},{word:"Huntington’s disease",phonetic:"",meaning:"A genetic disorder characterised by the progressive degeneration of nerve cells in the brain, reducing the affected individual’s ability to think, talk and move.",example:"亨廷顿病",image_url:"",emoji:"🔬"},{word:"Ligases",phonetic:"",meaning:"Enzymes which catalyse the joining of two molecules, usually via a hydrolysis reaction.",example:"连接酶",image_url:"",emoji:"🔬"},{word:"Liposome",phonetic:"",meaning:"A vesicle with a lipid bilayer that can be used to administer medication.",example:"脂质体",image_url:"",emoji:"🔬"},{word:"Marker gene",phonetic:"",meaning:"An additional gene inserted into a plasmid that is used to aid in the identification of host cells that have taken up the desired gene. Marker genes are easily recognisable, e.g. fluoresce, provide antibiotic resistance.",example:"标记基因",image_url:"",emoji:"🔬"},{word:"Microarrays",phonetic:"",meaning:"A method of DNA sequencing. The DNA sample hybridises with fragments of single-stranded DNA bound to a chip.",example:"微阵列",image_url:"",emoji:"🔬"},{word:"Plasmids",phonetic:"",meaning:"Loops of DNA found in the cytoplasm of prokaryotic cells. They can be used as vectors in genetic engineering.",example:"质粒",image_url:"",emoji:"🔬"},{word:"Polymerase chain reaction (PCR)",phonetic:"",meaning:"An in vitro technique used to rapidly amplify fragments of DNA.",example:"聚合酶链式反应 (PCR)",image_url:"",emoji:"🔬"},{word:"Promoter sequence",phonetic:"",meaning:"A region upstream of a gene where the transcription initiation complex is formed.",example:"启动子序列",image_url:"",emoji:"🔬"},{word:"Recombinant DNA",phonetic:"",meaning:"A combination of DNA from two different organisms.",example:"重组DNA",image_url:"",emoji:"🔬"},{word:"Recombinant protein",phonetic:"",meaning:"A protein produced as a result of the expression of recombinant DNA in a cell.",example:"重组蛋白",image_url:"",emoji:"🔬"},{word:"Restriction endonucleases",phonetic:"",meaning:"Enzymes that cut DNA molecules at recognition sequences, creating sticky ends.",example:"限制性核酸内切酶",image_url:"",emoji:"🔬"},{word:"Reverse transcriptase",phonetic:"",meaning:"A viral enzyme which produces cDNA from an RNA template.",example:"逆转录酶",image_url:"",emoji:"🔬"},{word:"Severe combined immunodeficiency (SCID)",phonetic:"",meaning:"A group of polygenic diseases which disrupt the development of B and T lymphocytes, resulting in persistent infection.",example:"重症联合免疫缺陷 (SCID)",image_url:"",emoji:"🔬"},{word:"Sickle cell anaemia",phonetic:"",meaning:"A disease characterised by hook-shaped red blood cells. A missense point mutation of GAG to GTG in the HbA (normal) allele for the β-globin polypeptide results in the HbS (sickle cell) allele of the gene.",example:"镰状细胞贫血",image_url:"",emoji:"🔬"},{word:"Taq polymerase",phonetic:"",meaning:"A DNA polymerase from a bacterial species which is adapted to live in extreme heat. It is used in PCR technology to produce fragments.",example:"Taq DNA聚合酶",image_url:"",emoji:"🔬"},{word:"Vector",phonetic:"",meaning:"A carrier used to transfer a gene from one organism to another, e.g. plasmid, virus, liposome.",example:"载体",image_url:"",emoji:"🔬"}]}];export{e as CAIE_BIOLOGY_ALEVEL_BANKS};
